:root{
  --bg:#0a0f18;--surface:#111925;--surface-2:#172232;--card:#121c2a;--text:#f7f9fc;--muted:#a8b5c7;
  --line:#28364a;--line-strong:#3a4d67;--accent:#ff4053;--accent-2:#806cff;--gold:#f5b942;--blue:#4f9fff;--green:#39c982;--cyan:#45d8ff;
  --shadow:0 18px 48px rgba(0,0,0,.28);--shadow-soft:0 10px 28px rgba(0,0,0,.18);--radius:18px;--radius-lg:24px;--nav-h:74px;--max:1180px;
}
body.light{
  --bg:#f6f8fc;--surface:#ffffff;--surface-2:#eef3fb;--card:#ffffff;--text:#121a2a;--muted:#506078;
  --line:#d4deeb;--line-strong:#becbdc;--shadow:0 15px 38px rgba(20,36,58,.10);--shadow-soft:0 8px 22px rgba(20,36,58,.08)
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;color-scheme:dark;scroll-padding-top:calc(var(--nav-h) + 12px)}
body.light{color-scheme:light}
body{margin:0;min-width:0;max-width:100%;overflow-x:hidden;background:
  radial-gradient(circle at 9% 11%,rgba(79,159,255,.075),transparent 32rem),
  radial-gradient(circle at 91% 34%,rgba(128,108,255,.07),transparent 34rem),
  radial-gradient(circle at 48% 84%,rgba(255,64,83,.045),transparent 30rem),var(--bg);
  color:var(--text);font-family:"Segoe UI Variable Text","Aptos",Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;line-height:1.45}
body.light{background:
  radial-gradient(circle at 8% 7%,rgba(79,159,255,.10),transparent 30rem),
  radial-gradient(circle at 92% 24%,rgba(128,108,255,.08),transparent 31rem),
  radial-gradient(circle at 48% 76%,rgba(255,64,83,.045),transparent 29rem),#f6f8fc}
button,input,select{font:inherit}button{color:inherit}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}
h1,h2,h3,.brand-main{font-family:"Segoe UI Variable Display","Aptos Display","Segoe UI Variable Text","Segoe UI",Inter,ui-sans-serif,system-ui,sans-serif}.section-head h2,.directory-hero h1,.club-identity h1,.modal-copy h2{font-weight:850}.section-head p,.directory-hero p,.about-home-copy>p{font-weight:450}
.hidden{display:none!important}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.container{width:min(var(--max),calc(100% - 40px));margin:auto;min-width:0}.muted{color:var(--muted)}
.eyebrow{font-size:11px;font-weight:950;letter-spacing:.17em;text-transform:uppercase;color:var(--accent)}
:focus-visible{outline:3px solid rgba(79,159,255,.58);outline-offset:3px}
.skip-link{position:fixed;left:14px;top:-80px;z-index:400;background:var(--text);color:var(--bg);padding:10px 14px;border-radius:10px;font-weight:900;transition:top .15s ease}.skip-link:focus{top:12px}

/* NAVIGATION */
.nav{height:var(--nav-h);position:sticky;top:0;z-index:90;background:rgba(7,11,18,.90);backdrop-filter:blur(18px);border-bottom:1px solid rgba(255,255,255,.08)}
body.light .nav{background:rgba(255,255,255,.92);border-color:var(--line)}
.nav-inner{height:100%;display:grid;grid-template-columns:230px 1fr 230px;align-items:center;gap:22px;min-width:0}
.brand{display:flex;flex-direction:column;justify-content:center;line-height:1;min-width:0}.brand-main{font-size:24px;font-weight:900;letter-spacing:.045em;white-space:nowrap}.brand-star{color:var(--accent);margin-left:4px}.brand small{font-size:7px;letter-spacing:.16em;color:var(--muted);margin-top:6px;white-space:nowrap}
.nav-links{height:100%;display:flex;justify-content:center;align-items:center;gap:30px;min-width:0}.nav-links a{height:100%;display:flex;align-items:center;font-size:15.5px;line-height:1;font-weight:760;color:var(--muted);padding:2px 3px 0;position:relative;white-space:nowrap}.nav-links a:hover,.nav-links a.active{color:var(--text)}.nav-links a.active:after{content:"";position:absolute;left:2px;right:2px;bottom:12px;height:2px;border-radius:99px;background:linear-gradient(90deg,var(--accent),#ff7b86)}
.nav-actions{display:flex;justify-content:flex-end;gap:8px;align-items:center}.icon-btn,.menu-btn{width:38px;height:38px;border-radius:50%;border:1px solid rgba(255,255,255,.10);background:#151d28;color:#edf2f8;display:grid;place-items:center;cursor:pointer;transition:background .16s ease,border-color .16s ease,transform .16s ease}.icon-btn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.menu-btn{display:none;font-size:18px}.mobile-theme-toggle{display:none}
body.light .icon-btn,body.light .menu-btn{background:#fff;color:#1c2735;border-color:#d6e0eb}
@media(hover:hover) and (pointer:fine){.icon-btn:hover,.menu-btn:hover{background:#202b38;border-color:#43536a;transform:translateY(-1px)}body.light .icon-btn:hover,body.light .menu-btn:hover{background:#f3f7fb;border-color:#bac8d9}}

/* SEARCH */
.search-panel{position:fixed;top:84px;right:24px;width:min(520px,calc(100vw - 48px));z-index:120;background:var(--surface);border:1px solid var(--line);border-radius:16px;box-shadow:0 24px 70px rgba(0,0,0,.35);padding:12px}.search-row{display:flex;gap:8px}.search-row input{flex:1;min-width:0;border:1px solid var(--line);background:var(--surface-2);color:var(--text);border-radius:12px;padding:12px 13px;outline:none}.search-row input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(79,159,255,.10)}.search-results{margin-top:8px;max-height:330px;overflow:auto;overscroll-behavior:contain}.search-result{display:flex;align-items:center;gap:12px;padding:11px;border:1px solid transparent;border-radius:12px;cursor:pointer}.search-result:hover,.search-result.active{background:var(--surface-2);border-color:rgba(79,159,255,.34)}.search-result strong{display:block;font-size:13px}.search-result span{font-size:11px;color:var(--muted)}.result-badge{font-size:9px!important;font-weight:950;letter-spacing:.12em;color:var(--accent)!important}.search-group-label{padding:10px 11px 5px;font-size:9px;font-weight:950;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}.search-hint{padding:9px 11px 3px;font-size:10px;color:var(--muted);border-top:1px solid var(--line);margin-top:5px}.search-hint kbd{font:inherit;border:1px solid var(--line);border-bottom-width:2px;border-radius:5px;padding:1px 5px;background:var(--surface-2);color:var(--text)}

/* HERO — abstract discovery canvas, intentionally not a campus/trekking photo */
.hero{min-height:535px;display:flex;align-items:center;position:relative;overflow:hidden;background:
  radial-gradient(circle at 76% 24%,rgba(69,216,255,.18),transparent 19rem),
  radial-gradient(circle at 88% 72%,rgba(128,108,255,.24),transparent 22rem),
  radial-gradient(circle at 54% 105%,rgba(255,64,83,.13),transparent 25rem),
  linear-gradient(125deg,#08111f 0%,#0d1728 42%,#17172d 70%,#211526 100%)}
.hero:before{content:"";position:absolute;inset:0;opacity:.72;background:
  radial-gradient(circle at 72% 37%,rgba(255,255,255,.82) 0 2px,transparent 2.6px),
  radial-gradient(circle at 83% 24%,rgba(69,216,255,.95) 0 3px,transparent 3.6px),
  radial-gradient(circle at 90% 49%,rgba(128,108,255,.92) 0 3px,transparent 3.6px),
  radial-gradient(circle at 66% 67%,rgba(255,64,83,.85) 0 2.5px,transparent 3.2px),
  repeating-linear-gradient(118deg,transparent 0 62px,rgba(255,255,255,.018) 63px 64px);pointer-events:none}
.hero:after{content:"";position:absolute;inset:auto 0 0;height:150px;background:linear-gradient(transparent,var(--bg));pointer-events:none}
.hero-content{position:relative;z-index:2;padding:76px 0 96px}.hero-mark{font-size:11px;font-weight:900;letter-spacing:.18em;text-transform:uppercase;color:#bfeaff}.hero h1{font-size:clamp(50px,6vw,80px);line-height:.94;letter-spacing:-.052em;margin:18px 0;max-width:800px;color:#fff;text-shadow:0 8px 32px rgba(0,0,0,.28)}.hero p{font-size:18px;line-height:1.62;max-width:620px;color:#e6edf7;margin:0 0 28px;text-shadow:0 3px 18px rgba(0,0,0,.18)}.cta{display:inline-flex;align-items:center;gap:12px;border:0;border-radius:999px;padding:13px 19px;background:linear-gradient(135deg,var(--accent),#ff6472);color:#fff;font-weight:900;font-size:13px;box-shadow:0 12px 30px rgba(255,64,83,.28);cursor:pointer;transition:transform .17s ease,box-shadow .17s ease}.cta:active{transform:scale(.98)}
body.light .hero{background:
  radial-gradient(circle at 76% 24%,rgba(69,216,255,.20),transparent 19rem),
  radial-gradient(circle at 88% 72%,rgba(128,108,255,.18),transparent 22rem),
  radial-gradient(circle at 54% 105%,rgba(255,64,83,.10),transparent 25rem),
  linear-gradient(125deg,#13263f 0%,#1b3150 42%,#292b50 70%,#42283b 100%)}
body.light .hero:after{background:linear-gradient(transparent,var(--bg))}
@media(hover:hover) and (pointer:fine){.cta:hover{transform:translateY(-2px);box-shadow:0 16px 34px rgba(255,64,83,.35)}}

/* PAGE RHYTHM */
main{padding:0 0 74px}.home-section,.page-section{padding:58px 0}.home-section,.gallery-section{position:relative;border-top:1px solid var(--line)}.home-section:before,.gallery-section:before{content:"";position:absolute;top:-1px;left:50%;transform:translateX(-50%);width:min(420px,45vw);height:1px;background:linear-gradient(90deg,transparent,rgba(79,159,255,.52),rgba(255,64,83,.48),transparent)}
body.light .home-section:nth-of-type(1){background:linear-gradient(180deg,rgba(79,159,255,.045),transparent 78%)}body.light .home-section:nth-of-type(2){background:linear-gradient(180deg,rgba(255,64,83,.04),transparent 78%)}body.light .gallery-section{background:linear-gradient(180deg,rgba(128,108,255,.045),rgba(69,216,255,.02))}
.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:22px}.section-head h2{font-size:34px;letter-spacing:-.032em;margin:6px 0;line-height:1.08}.section-head p{margin:0;max-width:680px;line-height:1.6}.view-all{font-size:12px;font-weight:950;color:var(--muted);white-space:nowrap}.view-all:hover{color:var(--text)}
.empty,.load-error{grid-column:1/-1;border:1px dashed var(--line);border-radius:16px;padding:24px;text-align:center;color:var(--muted);background:color-mix(in srgb,var(--surface) 78%,transparent)}.load-error strong{display:block;color:var(--text);font-size:15px;margin-bottom:6px}.load-error .btn{margin-top:12px}

/* SHARED CARDS / BUTTONS */
.club-card,.event-card,.home-event-card{border:1px solid var(--line);border-radius:var(--radius);box-shadow:0 1px 0 rgba(255,255,255,.02);transition:transform .2s ease,border-color .2s ease,box-shadow .2s ease;background:var(--card)}
body.light .club-card,body.light .event-card,body.light .home-event-card{border-color:#d5dfeb;box-shadow:0 8px 22px rgba(29,48,74,.055)}
.clickable-card{cursor:pointer}.card-actions,.home-event-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{min-height:36px;border:1px solid var(--line);background:var(--surface-2);color:var(--text);border-radius:10px;padding:9px 12px;font-size:11px;font-weight:950;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;line-height:1.1;transition:filter .15s ease,transform .15s ease,border-color .15s ease,background .15s ease}.btn.primary{background:var(--text);color:var(--bg);border-color:var(--text)}.btn.view-club-btn{background:rgba(79,159,255,.12);border-color:rgba(79,159,255,.42);color:#a5cdff}.btn.register-btn{background:linear-gradient(135deg,#e93446,#ff5968);border-color:#ff6674;color:#fff;box-shadow:0 8px 20px rgba(255,64,83,.16)}body.light .btn.view-club-btn{background:#edf5ff;border-color:#bfd9fb;color:#255f9c}body.light .btn.register-btn{color:#fff}.btn:active{transform:scale(.98)}
.save-btn,.share-btn{width:36px;height:36px;flex:0 0 36px;border-radius:10px;border:1px solid var(--line);background:var(--surface-2);color:var(--text);display:grid;place-items:center;cursor:pointer;transition:transform .14s ease,border-color .14s ease,background .14s ease,color .14s ease}.save-btn svg,.share-btn svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8}.save-btn.saved{background:rgba(128,108,255,.16);border-color:rgba(128,108,255,.48);color:#cec7ff}.save-btn.saved svg{fill:currentColor}.share-btn.sharing{background:rgba(79,159,255,.18);border-color:rgba(79,159,255,.60);transform:scale(.96)}.share-btn.copied{background:#173c2b;border-color:var(--green);color:#baf2d1}
@media(hover:hover) and (pointer:fine){.club-card:hover,.event-card:hover,.home-event-card:hover{transform:translateY(-5px);box-shadow:0 20px 48px rgba(0,0,0,.24)}.club-card:hover{border-color:rgba(79,159,255,.52)}.event-card:hover,.home-event-card:hover{border-color:rgba(255,64,83,.46)}body.light .club-card:hover,body.light .event-card:hover,body.light .home-event-card:hover{box-shadow:0 20px 42px rgba(29,48,74,.13)}.btn:hover{filter:brightness(1.07);transform:translateY(-1px)}.btn.view-club-btn:hover{background:rgba(79,159,255,.19);border-color:rgba(79,159,255,.66)}.btn.register-btn:hover{box-shadow:0 11px 24px rgba(255,64,83,.24)}.save-btn:hover,.share-btn:hover{transform:translateY(-1px);border-color:var(--line-strong)}}

/* MEDIA / IMAGE FALLBACKS */
.media-shell{position:relative;overflow:hidden;background:linear-gradient(135deg,#0e1520,#172232);isolation:isolate}.media-shell:before{content:"";position:absolute;inset:-20px;background-image:var(--media);background-size:cover;background-position:center;filter:blur(20px);opacity:.34;transform:scale(1.12);z-index:-1}.media-shell>img{position:relative;width:100%;height:100%;object-fit:contain;z-index:2;opacity:0;transition:opacity .28s ease}.media-shell>img.loaded{opacity:1}.media-shell.media-error:before{display:none}.media-shell.media-error{background:linear-gradient(135deg,rgba(79,159,255,.12),rgba(128,108,255,.11),rgba(255,64,83,.08))}.media-fallback{position:absolute;inset:0;display:grid;place-items:center;z-index:1;color:#7d8ca0;font-size:38px;font-weight:950;letter-spacing:.04em}.media-fallback>div{display:grid;place-items:center;gap:6px}.media-fallback small{font-size:9px;letter-spacing:.13em;text-transform:uppercase;margin-top:5px}.zoomable-card-media,.club-cover-click,.zoomable-logo{cursor:zoom-in}

/* CLUB CARDS */
.club-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.club-card{overflow:hidden;background:linear-gradient(180deg,rgba(69,216,255,.032),transparent 28%),var(--card);min-width:0}.club-banner{aspect-ratio:16/8.6}.club-body{padding:18px;position:relative;min-width:0}.club-logo{position:absolute;right:18px;top:-34px;width:68px;height:68px;border-radius:50%;background:var(--surface);border:4px solid var(--card);object-fit:contain;padding:6px;box-shadow:0 8px 18px rgba(0,0,0,.22)}.zoomable-logo{transition:filter .18s ease}.club-body h3{font-size:19px;line-height:1.2;margin:0 80px 7px 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.club-body p{font-size:13px;line-height:1.55;color:var(--muted);margin:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:60px}.club-body .card-actions{margin-top:16px}
body.light .club-card{background:linear-gradient(180deg,#fff 0%,#fff 70%,#f7f5ff 100%)}
@media(hover:hover) and (pointer:fine){.zoomable-logo:hover{filter:brightness(1.08)}}

/* HOME EVENTS */
.home-event-list{display:grid;gap:14px}.home-event-card{display:grid;grid-template-columns:180px minmax(0,1fr);overflow:hidden;min-height:152px;background:linear-gradient(90deg,rgba(255,64,83,.04),transparent 40%),var(--card);min-width:0}.home-event-media-wrap{position:relative;min-height:152px;overflow:hidden}.home-event-media{height:100%;min-height:152px}.home-event-copy{padding:18px 18px 16px;display:flex;flex-direction:column;min-width:0}.home-event-copy h3{font-size:20px;line-height:1.2;margin:4px 0 6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.event-club{font-size:11px;font-weight:950;color:#ff7080;text-transform:uppercase;letter-spacing:.08em}.event-meta{display:flex;flex-wrap:wrap;gap:8px 16px;color:var(--muted);font-size:12px;margin-top:4px}.home-event-copy p{font-size:13px;color:var(--muted);line-height:1.5;margin:9px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.home-event-actions{margin-top:auto;padding-top:12px}.date-badge{position:absolute;left:10px;bottom:10px;z-index:5;width:48px;height:52px;border-radius:12px;background:rgba(7,11,18,.88);backdrop-filter:blur(8px);display:grid;place-items:center;color:#fff;line-height:1;text-align:center;border:1px solid rgba(255,255,255,.14)}.date-badge strong{font-size:19px}.date-badge span{font-size:9px;font-weight:950;letter-spacing:.1em}
body.light .home-event-card{background:linear-gradient(135deg,#fff 0%,#f7fbff 63%,#fff5f6 100%)}body.light .event-club{color:#d83349}

/* DIRECTORY PAGES */
.page-wrap{display:none}.page-wrap.active{display:block}.directory-hero{min-height:240px;border-radius:var(--radius-lg);margin:34px 0 28px;padding:40px;display:flex;align-items:flex-end;position:relative;overflow:hidden;border:1px solid var(--line);box-shadow:var(--shadow-soft);background-color:var(--surface)}.directory-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,9,16,.58),rgba(5,9,16,.20) 65%,rgba(5,9,16,.08));pointer-events:none}.directory-hero>div{position:relative;z-index:2}.clubs-hero{background:radial-gradient(circle at 82% 28%,rgba(69,216,255,.28),transparent 16rem),radial-gradient(circle at 68% 78%,rgba(128,108,255,.24),transparent 18rem),radial-gradient(circle at 96% 80%,rgba(255,64,83,.17),transparent 14rem),linear-gradient(125deg,#0d1b2d 0%,#132a3a 44%,#24203c 72%,#2b172d 100%)}.events-hero{background:radial-gradient(circle at 84% 30%,rgba(255,64,83,.28),transparent 16rem),radial-gradient(circle at 70% 78%,rgba(128,108,255,.26),transparent 19rem),radial-gradient(circle at 96% 72%,rgba(69,216,255,.16),transparent 14rem),linear-gradient(125deg,#21111c 0%,#28162d 43%,#20213c 72%,#10293a 100%)}.about-hero{background:radial-gradient(circle at 78% 28%,rgba(69,216,255,.24),transparent 28%),radial-gradient(circle at 88% 78%,rgba(128,108,255,.26),transparent 30%),linear-gradient(135deg,#111b2c 0%,#18162c 52%,#251426 100%)}.directory-hero h1{font-size:44px;margin:8px 0 8px;letter-spacing:-.038em;color:#fff;font-weight:850}.directory-hero p{margin:0;color:#e8eef7;max-width:660px;line-height:1.6;font-size:15px}.directory-hero .eyebrow{color:#ff8791}.filters-row{display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between;margin-bottom:18px}.pills{display:flex;gap:8px;flex-wrap:wrap}.pill{border:1px solid var(--line);background:var(--surface);color:var(--muted);border-radius:999px;padding:9px 13px;font-size:11px;font-weight:950;cursor:pointer;transition:background .15s ease,border-color .15s ease,color .15s ease}.pill.active{background:linear-gradient(135deg,#28394f,#6959d6);color:#fff;border-color:transparent}.sort{display:flex;align-items:center;gap:9px;font-size:11px;color:var(--muted);font-weight:850}.sort select{background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:999px;padding:9px 30px 9px 12px}.event-count{font-size:12px;color:var(--muted)}
.event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.event-card{overflow:hidden;display:flex;flex-direction:column;min-width:0;background:linear-gradient(180deg,rgba(128,108,255,.04),transparent 28%),var(--card)}.event-poster-wrap{position:relative;aspect-ratio:4/3;background:#0f1319;overflow:hidden}.event-poster{height:100%;width:100%}.event-poster-wrap>.save-btn{position:absolute;right:10px;top:10px;z-index:5;background:rgba(7,11,18,.82);color:#fff;border-color:rgba(255,255,255,.15)}.event-body{padding:17px;display:flex;flex-direction:column;flex:1;min-width:0}.status{display:inline-flex;align-self:flex-start;border:1px solid transparent;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:950;letter-spacing:.1em;text-transform:uppercase;background:#293342;color:#cad3df;margin-bottom:9px}.status.today{background:rgba(255,64,83,.16);color:#ff8b96;border-color:rgba(255,64,83,.28)}.event-body h3{font-size:19px;line-height:1.2;margin:0 0 7px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.event-body p{font-size:12px;line-height:1.55;color:var(--muted);display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;min-height:56px}.event-body .card-actions{margin-top:auto;padding-top:8px}
body.light .event-card{background:linear-gradient(135deg,#fff 0%,#f7fbff 66%,#fff5f6 100%)}

/* GALLERY */
.gallery-section{overflow:hidden;padding:60px 0}.gallery-viewport{overflow:hidden;width:100%;padding:18px 0;mask-image:linear-gradient(90deg,transparent,#000 4%,#000 96%,transparent)}.gallery-track,.club-gallery-track{display:flex;gap:14px;width:max-content;will-change:transform;animation:marquee 34s linear infinite}.gallery-track img,.club-gallery-track img{width:240px;height:160px;object-fit:cover;border-radius:16px;flex:none;cursor:zoom-in;border:1px solid rgba(255,255,255,.10);box-shadow:0 8px 22px rgba(0,0,0,.12);transition:transform .22s ease,box-shadow .22s ease,filter .22s ease;position:relative}.gallery-track img[loading],.club-gallery-track img[loading]{background:var(--surface-2)}@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(calc(-50% - 7px))}}
@media(hover:hover) and (pointer:fine){.gallery-track img:hover,.club-gallery-track img:hover{transform:scale(1.07);box-shadow:0 18px 42px rgba(0,0,0,.35);filter:saturate(1.08) brightness(1.03);z-index:8}}

/* ABOUT — intentionally static: no pop-up/lift hover effect */
