.about-story-grid{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(300px,.55fr);gap:18px;margin-top:18px}.about-story-main,.about-side-note{border:1px solid var(--line);border-radius:22px;background:var(--surface);padding:30px;overflow:hidden;position:relative}.about-story-main{background:linear-gradient(135deg,rgba(79,159,255,.07),transparent 38%),var(--surface)}.about-story-main h2{font-size:34px;letter-spacing:-.035em;margin:8px 0 16px}.about-story-main>p{color:var(--muted);line-height:1.78;max-width:760px}.about-story-main .about-question{font-size:19px;color:var(--text);font-weight:850;margin:0 0 12px}.about-side-note{min-height:310px;display:flex;align-items:flex-end;background:linear-gradient(145deg,rgba(128,108,255,.16),rgba(69,216,255,.055) 60%,rgba(255,64,83,.11)),var(--surface)}.about-side-note h3{font-size:29px;letter-spacing:-.035em;line-height:1.08;margin:8px 0 10px}.about-side-note p{color:var(--muted);font-size:13px;line-height:1.65;margin:0}.about-orbit{position:absolute;right:-18px;top:-28px;width:190px;height:190px;border:1px solid rgba(255,255,255,.08);border-radius:50%}.about-orbit:before,.about-orbit:after{content:"";position:absolute;border:1px solid rgba(255,255,255,.07);border-radius:50%}.about-orbit:before{inset:26px}.about-orbit:after{inset:54px}.about-orbit span{position:absolute;width:8px;height:8px;border-radius:50%;background:var(--cyan);box-shadow:0 0 18px rgba(69,216,255,.7)}.about-orbit span:nth-child(1){left:35px;top:27px}.about-orbit span:nth-child(2){right:20px;top:84px;background:var(--accent-2);box-shadow:0 0 18px rgba(128,108,255,.7)}.about-orbit span:nth-child(3){left:85px;bottom:13px;background:var(--accent);box-shadow:0 0 18px rgba(255,64,83,.6)}
