/* === KAMPUS MAIN-CANDIDATE FINAL DESIGN SYSTEM === */
:root{
  --text:#f6f8fc;--heading:#fff;--body-copy:#dde6f2;--muted:#aeb9ca;
  --font-body:"Aptos","Segoe UI Variable Text","Segoe UI",Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,sans-serif;
  --font-display:"Aptos Display","Segoe UI Variable Display","Segoe UI",Inter,ui-sans-serif,system-ui,sans-serif;
  --fs-xs:11px;--fs-sm:13px;--fs-md:15px;--fs-lg:18px;--fs-h3:20px;--fs-h2:clamp(30px,4vw,42px);--fs-h1:clamp(48px,6vw,80px);
  --tap:44px;--content-gap:18px;
}
