body{min-height:100dvh;font-family:var(--font-body);font-weight:450;letter-spacing:-.004em}
h1,h2,h3,.brand-main{font-family:var(--font-display);letter-spacing:-.035em;color:var(--heading)}
p{color:var(--body-copy)}
.nav{isolation:isolate}.nav-inner>*{min-width:0}.nav-links a{font-size:16px;font-weight:720;letter-spacing:-.01em}.brand-main{font-weight:880;letter-spacing:.025em}

/* Photo hero: nature / mountain discovery background. */
.hero{min-height:560px;background-image:linear-gradient(90deg,rgba(5,12,15,.88) 0%,rgba(5,12,15,.72) 34%,rgba(5,12,15,.40) 62%,rgba(5,12,15,.18) 100%),linear-gradient(180deg,rgba(4,10,12,.03),rgba(4,10,12,.10) 64%,rgba(4,10,12,.72)),url("https://images.pexels.com/photos/14856412/pexels-photo-14856412.jpeg?auto=compress&cs=tinysrgb&w=2200");background-size:cover;background-position:center 52%;background-repeat:no-repeat;isolation:isolate}
.hero:before{opacity:1;background:radial-gradient(circle at 18% 24%,rgba(79,159,255,.16),transparent 24rem),radial-gradient(circle at 80% 35%,rgba(128,108,255,.08),transparent 22rem)}
.hero-content{padding:82px 0 104px}.hero-mark{color:#b9dcff;font-size:11.5px;font-weight:900;letter-spacing:.19em;text-shadow:0 2px 18px rgba(0,0,0,.36)}
.hero h1{font-size:var(--fs-h1);font-weight:880;line-height:.95;letter-spacing:-.052em;color:#fff;text-shadow:0 10px 34px rgba(0,0,0,.38)}.hero p{font-size:18px;font-weight:470;line-height:1.62;color:#eef4fb;text-shadow:0 4px 20px rgba(0,0,0,.35)}
body.light .hero{background-image:linear-gradient(90deg,rgba(5,13,14,.78) 0%,rgba(5,13,14,.62) 36%,rgba(5,13,14,.30) 65%,rgba(5,13,14,.12) 100%),linear-gradient(180deg,rgba(6,14,15,.02),rgba(6,14,15,.06) 65%,rgba(6,14,15,.44)),url("https://images.pexels.com/photos/14856412/pexels-photo-14856412.jpeg?auto=compress&cs=tinysrgb&w=2200")}.hero h1,.hero p,.hero-mark,body.light .hero h1,body.light .hero p,body.light .hero-mark{color:#fff}

/* Rhythm + typography */
main{padding-bottom:64px}.home-section,.page-section{padding:54px 0}.gallery-section{padding:56px 0}.section-head{margin-bottom:24px}.section-head h2{font-size:var(--fs-h2);font-weight:860;line-height:1.05}.section-head p{font-size:14px;line-height:1.6;max-width:700px}.eyebrow{font-size:10.5px;letter-spacing:.18em}.view-all{font-size:12px;font-weight:850}
.home-section,.gallery-section{border-top:1px solid var(--line)}.home-section:before,.gallery-section:before{width:min(420px,42vw);background:linear-gradient(90deg,transparent,rgba(79,159,255,.46),rgba(255,64,83,.40),transparent)}
body.light .home-section:nth-of-type(1){background:linear-gradient(180deg,rgba(79,159,255,.04),transparent 72%)}body.light .home-section:nth-of-type(2){background:linear-gradient(180deg,rgba(255,64,83,.035),transparent 72%)}

/* Unified cards + buttons */
.club-card,.event-card,.home-event-card,.recent-card{border-radius:18px;border:1px solid var(--line);box-shadow:0 1px 0 rgba(255,255,255,.025),0 10px 26px rgba(0,0,0,.08);background:var(--card)}
