.btn,.save-btn,.share-btn,.icon-btn,.menu-btn,.back-btn,.saved-close,.close-btn{min-height:var(--tap);touch-action:manipulation}.btn{min-height:40px;border-radius:11px;padding:9px 14px;font-weight:850;font-size:12px;display:inline-flex;align-items:center;justify-content:center;gap:7px}.btn.view-club-btn{background:rgba(79,159,255,.10);border-color:rgba(79,159,255,.36);color:#b8d9ff}.btn.register-btn{background:linear-gradient(135deg,#ff4053,#ff6674);border-color:#ff4053;color:#fff}.btn.primary{background:linear-gradient(135deg,#26344a,#1e2a3c);border-color:#3b4d67;color:#fff}body.light .btn.primary{background:#172033;border-color:#172033;color:#fff}body.light .btn.view-club-btn{background:#edf6ff;border-color:#b7d7ff;color:#205b9e}.save-btn,.share-btn{width:40px;height:40px;flex:0 0 40px;border-radius:11px}
@media(hover:hover) and (pointer:fine){.club-card:hover,.event-card:hover,.home-event-card:hover,.recent-card:hover{transform:translateY(-3px);box-shadow:0 18px 42px rgba(0,0,0,.20)}body.light .club-card:hover,body.light .event-card:hover,body.light .home-event-card:hover,body.light .recent-card:hover{box-shadow:0 18px 38px rgba(29,48,74,.12)}.club-card:hover{border-color:rgba(79,159,255,.48)}.event-card:hover,.home-event-card:hover{border-color:rgba(255,64,83,.42)}.btn:hover{transform:translateY(-1px);filter:brightness(1.05)}}

/* Image system: consistent ratios, graceful placeholders, fade-in */
.media-shell{contain:paint;background:linear-gradient(135deg,#0e1723,#1b2839);position:relative;overflow:hidden}.media-shell:before{opacity:.28}.media-shell:after{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(110deg,transparent 20%,rgba(255,255,255,.07) 42%,transparent 64%);transform:translateX(-110%);animation:kampusShimmer 1.5s ease-in-out infinite;pointer-events:none}.media-shell:has(img.loaded):after,.media-shell.media-error:after{display:none}@keyframes kampusShimmer{to{transform:translateX(110%)}}
.media-shell>img{opacity:0;transition:opacity .28s ease,transform .25s ease}.media-shell>img.loaded{opacity:1}.media-fallback{color:#8fa1b8}.media-fallback .placeholder-mark{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,rgba(79,159,255,.15),rgba(128,108,255,.16));border:1px solid rgba(128,108,255,.25);font-size:22px}.media-fallback small{color:#a8b4c5}.club-banner{aspect-ratio:16/8.2}.event-poster-wrap{aspect-ratio:4/3}.home-event-media-wrap{background:#0e151f}.club-cover{aspect-ratio:16/6.4}

/* Club category identity */
.club-chip{display:inline-flex;align-items:center;gap:6px;width:max-content;max-width:100%;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:900;letter-spacing:.09em;text-transform:uppercase;border:1px solid var(--line);color:var(--muted);background:var(--surface-2);margin:0 0 8px}.club-chip:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--chip,#8fa2bb)}.club-chip[data-cat="Technical"]{--chip:#4f9fff}.club-chip[data-cat="Arts & Culture"]{--chip:#ff6c88}.club-chip[data-cat="Business"]{--chip:#f5b942}.club-chip[data-cat="Sports"]{--chip:#39c982}.club-chip[data-cat="Social Impact"]{--chip:#45d8ff}.club-chip[data-cat="Gaming & Quiz"]{--chip:#9f84ff}
.club-card{display:flex;flex-direction:column;height:100%;overflow:hidden}.club-body{display:flex;flex:1;flex-direction:column}.club-body h3{line-height:1.14}.club-body p{margin-bottom:0;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.club-body .card-actions{margin-top:auto;padding-top:16px}


.club-logo-initial{display:grid;place-items:center;background:linear-gradient(135deg,#edf4ff,#fff1f3);color:#1a2638;font-size:16px;font-weight:950;letter-spacing:.04em;border:1px solid var(--line)}

/* Event badges */
.event-badges{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-bottom:8px}.status{margin:0}.status.now{background:rgba(57,201,130,.16);color:#7ee0a9;border-color:rgba(57,201,130,.32)}.status.ended{background:rgba(148,158,171,.12);color:#9ca8b8;border-color:rgba(148,158,171,.24)}.fresh-badge,.featured-badge{display:inline-flex;align-items:center;border-radius:999px;padding:5px 8px;font-size:9px;font-weight:950;letter-spacing:.1em;text-transform:uppercase;border:1px solid rgba(79,159,255,.28);background:rgba(79,159,255,.10);color:#8fc4ff}.featured-badge{border-color:rgba(245,185,66,.30);background:rgba(245,185,66,.10);color:#ffd67d}
.home-event-card{height:100%;grid-template-columns:180px minmax(0,1fr)}.home-event-copy{min-height:0}.home-event-copy h3{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.home-event-actions{width:100%}.event-card{height:100%}.event-body{min-height:252px}.event-body p{min-height:56px}.event-body .card-actions{width:100%}.event-meta span{overflow-wrap:anywhere}

/* Featured event: shown only when Supabase row is explicitly marked featured/is_featured. */
.featured-event-wrap{margin:22px 0 28px}.featured-event{display:grid;grid-template-columns:minmax(260px,.82fr) 1.18fr;border:1px solid rgba(245,185,66,.28);border-radius:20px;overflow:hidden;background:linear-gradient(135deg,rgba(245,185,66,.065),rgba(128,108,255,.05)),var(--card);box-shadow:0 16px 40px rgba(0,0,0,.14)}.featured-event-media{min-height:250px}.featured-event-copy{padding:26px;display:flex;flex-direction:column}.featured-event-copy h2{font-size:30px;margin:8px 0 10px;line-height:1.05}.featured-event-copy p{color:var(--muted);line-height:1.58}.featured-event-copy .card-actions{margin-top:auto;padding-top:16px}

/* Directory headers + controls */
.directory-hero{position:relative;overflow:hidden;box-shadow:0 16px 42px rgba(0,0,0,.18);background-size:cover;background-repeat:no-repeat}.directory-hero:before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 82% 28%,rgba(255,255,255,.10),transparent 18rem),linear-gradient(135deg,rgba(79,159,255,.06),transparent 42%,rgba(128,108,255,.06))}.directory-hero>div{position:relative;z-index:2;max-width:760px}.clubs-hero{background-image:linear-gradient(90deg,rgba(7,13,22,.84) 0%,rgba(7,13,22,.68) 46%,rgba(7,13,22,.30) 100%),url("https://images.pexels.com/photos/7972544/pexels-photo-7972544.jpeg?auto=compress&cs=tinysrgb&w=1800");background-position:center 46%}.events-hero{background-image:linear-gradient(90deg,rgba(15,8,16,.86) 0%,rgba(15,8,16,.66) 46%,rgba(15,8,16,.28) 100%),url("https://images.pexels.com/photos/33953254/pexels-photo-33953254.jpeg?auto=compress&cs=tinysrgb&w=1800");background-position:center 48%}.about-hero{background:linear-gradient(125deg,#121d2f,#1b2d44 50%,#25213e)}.directory-hero h1,.directory-hero p,.directory-hero .eyebrow,body.light .directory-hero h1,body.light .directory-hero p,body.light .directory-hero .eyebrow{color:#fff}.filters-row{padding:2px 0}.pill,.sort select{min-height:38px}

/* Club profile hierarchy */
.club-page{scrollbar-gutter:stable;background:radial-gradient(circle at 8% 8%,rgba(79,159,255,.09),transparent 28rem),radial-gradient(circle at 94% 28%,rgba(128,108,255,.08),transparent 30rem),var(--bg)}.club-page-inner{padding-bottom:68px}.club-topbar{position:sticky;top:0;z-index:12;padding:12px 0;background:linear-gradient(var(--bg) 76%,transparent);backdrop-filter:blur(10px)}.club-hero-card{position:relative;border:1px solid var(--line);border-radius:22px;overflow:hidden;box-shadow:var(--shadow);background:var(--card)}.club-hero-card:after{content:"";position:absolute;inset:0 0 auto;height:4px;background:linear-gradient(90deg,var(--accent),var(--blue),var(--accent-2));pointer-events:none}.club-cover-click{background:var(--surface-2)}.club-identity{padding:0 28px 28px;background:linear-gradient(180deg,rgba(128,108,255,.05),transparent 58%)}.club-page-logo-wrap{width:112px;height:112px;margin-top:-54px;margin-bottom:14px;border-radius:50%;position:relative;z-index:4;background:var(--card);border:4px solid var(--card);box-shadow:0 12px 28px rgba(0,0,0,.24);display:grid;place-items:center;overflow:hidden}.club-page-logo-wrap img{width:100%;height:100%;object-fit:contain;background:#fff}.club-page-logo-fallback{font-size:34px;font-weight:950;color:var(--text)}.club-title-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.club-title-row h1{margin:0}.club-identity>p{max-width:780px;font-size:15px;line-height:1.62}.club-meta-grid{gap:12px}.club-meta-card{position:relative;overflow:hidden;padding:16px 16px 15px}.club-meta-card:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--meta-accent,var(--blue))}.club-meta-card:nth-child(1){--meta-accent:var(--accent)}.club-meta-card:nth-child(2){--meta-accent:var(--gold)}.club-meta-card:nth-child(3){--meta-accent:var(--blue)}.club-meta-card:nth-child(4){--meta-accent:var(--green)}.club-meta-card strong{font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}.club-meta-card div{margin-top:5px;overflow-wrap:anywhere}.club-section{scroll-margin-top:20px;border-radius:18px;padding:22px;border:1px solid var(--line);background:var(--card);margin-top:16px}.club-section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.club-section-head h2{margin:0;font-size:21px}.club-section:nth-of-type(1){border-top-color:rgba(69,216,255,.35)}.club-section:nth-of-type(2){border-top-color:rgba(128,108,255,.38)}.club-section:nth-of-type(3){border-top-color:rgba(255,64,83,.34)}.club-section:nth-of-type(4){border-top-color:rgba(245,185,66,.34)}

/* Event modal extras */
.modal{scrollbar-gutter:stable}.modal-description{overflow-wrap:anywhere}.modal-more{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}.modal-more h3{font-size:13px;margin:0 0 9px}.more-events{display:grid;gap:8px}.more-event{width:100%;display:grid;grid-template-columns:42px minmax(0,1fr) auto;gap:10px;align-items:center;text-align:left;border:1px solid var(--line);background:var(--surface-2);color:var(--text);border-radius:12px;padding:9px;cursor:pointer}.more-event-date{width:42px;height:42px;border-radius:10px;background:var(--card);display:grid;place-items:center;font-size:10px;font-weight:900;line-height:1.05}.more-event-copy{min-width:0}.more-event-copy strong{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.more-event-copy span{display:block;color:var(--muted);font-size:10px;margin-top:2px}.more-event-arrow{color:var(--muted)}

/* Empty/error states */
.empty,.load-error,.inline-loading{min-height:110px;display:grid;place-items:center;align-content:center;text-align:center;border:1px dashed var(--line);border-radius:15px;background:linear-gradient(135deg,rgba(79,159,255,.035),rgba(128,108,255,.035));color:var(--muted);padding:22px;grid-column:1/-1}.empty-state-icon{width:40px;height:40px;border-radius:13px;display:grid;place-items:center;background:var(--surface-2);border:1px solid var(--line);color:var(--blue);margin-bottom:9px;font-size:18px}.empty strong,.load-error strong{color:var(--text);font-size:14px}.empty span,.load-error div{font-size:12px;max-width:430px;line-height:1.5}.load-error .btn{margin-top:10px}

/* Saved events grouped by date */
.saved-panel{scrollbar-gutter:stable}.saved-group{padding:4px 0 8px}.saved-group-title{padding:9px 9px 5px;color:var(--muted);font-size:9px;font-weight:950;letter-spacing:.12em;text-transform:uppercase}.saved-item{margin:0;border-bottom:1px solid var(--line)}.saved-copy h4,.saved-copy p{max-width:100%}.saved-open{color:#ff7784}

/* Search result feedback */
.search-panel{scrollbar-gutter:stable}.search-result{min-height:52px}.search-result>div{min-width:0}.search-result strong,.search-result span{overflow-wrap:anywhere}.search-focus{position:relative;animation:searchPulse 1.6s ease}.search-focus:after{content:"FOUND";position:absolute;right:12px;top:12px;z-index:20;border-radius:999px;background:var(--blue);color:#fff;font-size:8px;font-weight:950;letter-spacing:.12em;padding:5px 7px;box-shadow:0 6px 18px rgba(79,159,255,.28)}@keyframes searchPulse{0%,100%{box-shadow:inherit}35%{box-shadow:0 0 0 4px rgba(79,159,255,.22),0 18px 42px rgba(0,0,0,.16)}}

/* Gallery motion: only useful motion, no hover pause. */
