/* ======================================================================
   KAMPUS — MAIN WEBSITE CANDIDATE VISUAL SYSTEM
   Minimal neutral UI. Photography carries the colour.
   ====================================================================== */
:root{
  --bg:#0b0d10;--surface:#111419;--surface-2:#181c22;--card:#14171c;
  --text:#f3f4f5;--heading:#ffffff;--body-copy:#d0d4d8;--muted:#9aa2ac;
  --line:#272c33;--line-strong:#39414b;--accent:#ff4053;--accent-2:#ff4053;
  --gold:#aa956f;--blue:#76849a;--green:#718b79;--cyan:#758b90;
  --shadow:0 18px 46px rgba(0,0,0,.30);--shadow-soft:0 9px 24px rgba(0,0,0,.18)
}
body.light{
  --bg:#f6f5f2;--surface:#ffffff;--surface-2:#f0efeb;--card:#ffffff;
  --text:#20262e;--heading:#171d25;--body-copy:#4f5760;--muted:#737b85;
  --line:#dfddd7;--line-strong:#c9c6bf;--accent:#ff4053;--accent-2:#ff4053;
  --gold:#8d7a59;--blue:#6b788b;--green:#667c6c;--cyan:#6e8185;
  --shadow:0 15px 36px rgba(29,34,39,.09);--shadow-soft:0 8px 20px rgba(29,34,39,.06)
}
body,body.light{background:var(--bg);color:var(--text)}
p{color:var(--body-copy)} .eyebrow{color:var(--accent)}

/* Official KAMPUS logo: fixed navy wordmark + red star in BOTH themes. */
.nav,body.light .nav{
  background:rgba(255,255,255,.97);border-bottom:1px solid #e3e7eb;
  box-shadow:0 1px 0 rgba(20,34,56,.035);backdrop-filter:blur(16px)
}
.brand{color:#172238}
.brand-main,.brand-main:visited{color:#172238!important;font-weight:900;letter-spacing:-.025em}
.brand-star{color:#ff4053!important;margin-left:5px;font-size:.98em}
.brand small{color:#65738a!important;font-weight:750;letter-spacing:.17em}
.nav-links a{color:#626d7b}
.nav-links a:hover,.nav-links a.active{color:#172238}
.nav-links a.active:after{background:#ff4053}
.nav-actions .icon-btn,.nav-actions .menu-btn,
body.light .nav-actions .icon-btn,body.light .nav-actions .menu-btn{
  width:40px;height:40px;min-width:40px;min-height:40px;max-width:40px;max-height:40px;
  flex:0 0 40px;aspect-ratio:1/1;padding:0;border-radius:50%;
  background:#f5f7f9;color:#243040;border-color:#dfe4ea
}
@media(hover:hover) and (pointer:fine){
  .nav-actions .icon-btn:hover,.nav-actions .menu-btn:hover,
  body.light .nav-actions .icon-btn:hover,body.light .nav-actions .menu-btn:hover{
    background:#edf1f4;border-color:#ccd3db;transform:translateY(-1px)
  }
}
.mobile-theme-toggle{background:#f5f7f9!important;color:#243040!important;border-color:#dfe4ea!important}
@media(max-width:760px){
  .nav-links{background:#fff!important;border-color:#e1e5ea!important}
  .nav-links a{color:#626d7b!important}
  .nav-links a.active{background:#f3f5f7!important;color:#172238!important}
  .nav-actions .icon-btn,.nav-actions .menu-btn,
  body.light .nav-actions .icon-btn,body.light .nav-actions .menu-btn{
    width:36px;height:36px;min-width:36px;min-height:36px;max-width:36px;max-height:36px;flex-basis:36px
  }
}
@media(max-width:390px){
  .nav-actions .icon-btn,.nav-actions .menu-btn,
  body.light .nav-actions .icon-btn,body.light .nav-actions .menu-btn{
    width:34px;height:34px;min-width:34px;min-height:34px;max-width:34px;max-height:34px;flex-basis:34px
  }
}

/* Homepage hero: embedded real CHRIST photo; never disappears in light mode. */
.hero{
  min-height:560px;
  background-image:
    linear-gradient(90deg,rgba(7,9,11,.82) 0%,rgba(7,9,11,.66) 38%,rgba(7,9,11,.33) 67%,rgba(7,9,11,.12) 100%),
    linear-gradient(180deg,rgba(7,9,11,.03),rgba(7,9,11,.06) 72%,rgba(7,9,11,.36)),
    url("data:image/webp;base64,");
  background-size:cover;background-position:center 48%;background-repeat:no-repeat;isolation:isolate
}
body.light .hero{
  background-image:
    linear-gradient(90deg,rgba(7,9,11,.68) 0%,rgba(7,9,11,.52) 38%,rgba(7,9,11,.22) 67%,rgba(7,9,11,.06) 100%),
    linear-gradient(180deg,rgba(7,9,11,.01),rgba(7,9,11,.04) 72%,rgba(7,9,11,.22)),
    url("data:image/webp;base64,");
  background-size:cover;background-position:center 48%;background-repeat:no-repeat
}
.hero:before,body.light .hero:before{opacity:1;background:linear-gradient(90deg,rgba(0,0,0,.05),transparent 60%)}
.hero:after,body.light .hero:after{height:70px;background:linear-gradient(transparent,var(--bg))}
.hero h1,.hero p,.hero-mark,body.light .hero h1,body.light .hero p,body.light .hero-mark{color:#fff}
.hero p,body.light .hero p{color:#f1f3f5}
.hero-mark,body.light .hero-mark{color:#f6f7f8}
.cta{background:#ff4053;color:#fff;box-shadow:0 12px 28px rgba(255,64,83,.20)}
@media(hover:hover) and (pointer:fine){.cta:hover{box-shadow:0 15px 32px rgba(255,64,83,.25)}}

/* Clubs + Events headers: photographic, neutral overlays only. */
.directory-hero{background-size:cover;background-repeat:no-repeat}
.directory-hero:before{background:linear-gradient(90deg,rgba(0,0,0,.16),transparent 62%)}
.directory-hero:after{background:linear-gradient(90deg,rgba(5,7,9,.63),rgba(5,7,9,.27) 68%,rgba(5,7,9,.09))}
.clubs-hero{
  background-image:linear-gradient(90deg,rgba(7,9,11,.78),rgba(7,9,11,.46) 54%,rgba(7,9,11,.16)),
  url("https://images.pexels.com/photos/7972544/pexels-photo-7972544.jpeg?auto=compress&cs=tinysrgb&w=1800")
}
.events-hero{
  background-image:linear-gradient(90deg,rgba(7,9,11,.80),rgba(7,9,11,.48) 54%,rgba(7,9,11,.16)),
  url("https://images.pexels.com/photos/33953254/pexels-photo-33953254.jpeg?auto=compress&cs=tinysrgb&w=1800")
}
.about-hero{background:linear-gradient(125deg,#121519,#1b1f24 58%,#22262c)}
.directory-hero .eyebrow{color:#ffd9dd}
.directory-hero h1,.directory-hero p,body.light .directory-hero h1,body.light .directory-hero p{color:#fff}

/* Calm, neutral cards and controls. */
.home-section,.gallery-section{background:transparent}
body.light .home-section:nth-of-type(1),body.light .home-section:nth-of-type(2),body.light .gallery-section{background:transparent}
.home-section:before,.gallery-section:before{background:linear-gradient(90deg,transparent,rgba(255,64,83,.28),transparent)}
.club-card,.event-card,.home-event-card,
body.light .club-card,body.light .event-card,body.light .home-event-card{background:var(--card);border-color:var(--line)}
.club-card,.event-card,.home-event-card{background:var(--card)}
.club-chip{background:rgba(255,64,83,.08)!important;border-color:rgba(255,64,83,.18)!important;color:#ff8f99!important}
body.light .club-chip{background:#fff1f3!important;border-color:#f1c7cc!important;color:#a82d3a!important}
.pill.active{background:var(--text);color:var(--bg);border-color:var(--text)}
.btn.primary{background:var(--text);color:var(--bg);border-color:var(--text)}
.btn.view-club-btn{background:transparent;border-color:var(--line-strong);color:var(--text)}
body.light .btn.view-club-btn{background:#fff;border-color:#d4d1ca;color:#2a3139}
.btn.register-btn{background:#ff4053;border-color:#ff4053;color:#fff;box-shadow:none}
.save-btn.saved{background:rgba(255,64,83,.11);border-color:rgba(255,64,83,.30);color:#ff8995}
body.light .save-btn.saved{background:#fff1f3;border-color:#efc1c6;color:#a92d3a}
.share-btn.copied{background:rgba(255,64,83,.11);border-color:rgba(255,64,83,.32);color:#ff96a0}
body.light .share-btn.copied{background:#fff1f3;border-color:#efc1c6;color:#a92d3a}

/* About section: remove multicolour decorative gradients. */
.about-home-panel,.about-story-main,.about-side-note,.about-value,.about-bottom-strip,
body.light .about-home-panel,body.light .about-story-main,body.light .about-side-note,
body.light .about-value,body.light .about-bottom-strip{background:var(--surface)!important;border-color:var(--line)!important}
.about-home-panel:after{opacity:.24}
.about-point,body.light .about-point{background:var(--surface-2)!important;border-color:var(--line)!important}
.about-point>span,.about-point:nth-child(2)>span,.about-point:nth-child(3)>span,
body.light .about-point>span,body.light .about-point:nth-child(2)>span,body.light .about-point:nth-child(3)>span{
  background:rgba(255,64,83,.07)!important;border-color:rgba(255,64,83,.15)!important;color:var(--text)!important
}
.about-value-icon,.about-value:nth-child(2) .about-value-icon,.about-value:nth-child(3) .about-value-icon{
  background:rgba(255,64,83,.07)!important;border-color:rgba(255,64,83,.15)!important;color:var(--text)!important
}

/* Club profile: BANNERS ARE STATIC. Only the logo can enlarge. */
.club-page{background:var(--bg)}
.club-hero-card,.club-section{background:var(--card);border-color:var(--line)}
.club-identity{background:transparent}
.club-hero-card:after{height:2px;background:#ff4053}
.club-cover-click,.club-card-cover-static,.zoomable-card-media{cursor:default!important}
.club-cover-click img,.club-card-cover-static img{cursor:default!important}
.club-page-logo-fallback,.club-logo-initial{display:none!important}
.club-page-logo-wrap{
  background:#fff;border-color:var(--card);cursor:zoom-in;
  transition:transform .18s ease,box-shadow .18s ease,filter .18s ease
}
.club-page-logo-wrap img{background:#fff}
.zoomable-logo{cursor:zoom-in!important;transition:transform .18s ease,box-shadow .18s ease,filter .18s ease}
@media(hover:hover) and (pointer:fine){
  .club-page-logo-wrap:hover{transform:translateY(-3px) scale(1.065);box-shadow:0 18px 34px rgba(0,0,0,.28);filter:brightness(1.02)}
  .club-logo.zoomable-logo:hover{transform:translateY(-2px) scale(1.07);box-shadow:0 12px 24px rgba(0,0,0,.25);filter:brightness(1.02)}
}
.club-body.no-logo h3{margin-right:0}
.club-meta-card,
body.light .club-meta-card,body.light .club-meta-card:nth-child(1),body.light .club-meta-card:nth-child(2),
body.light .club-meta-card:nth-child(3),body.light .club-meta-card:nth-child(4){background:var(--surface-2)!important;border-color:var(--line)!important}
.club-meta-card:before{background:#ff4053!important;opacity:.72}
.club-section:nth-of-type(1),.club-section:nth-of-type(2),.club-section:nth-of-type(3),.club-section:nth-of-type(4){border-top-color:var(--line)}
.club-section-head:before{background:#ff4053}
.club-share-btn{background:var(--surface-2);border-color:var(--line-strong);color:var(--text)}
body.light .club-share-btn{background:#fff;border-color:#d4d1ca;color:#2a3139}

/* Neutral supporting surfaces. */
.search-panel,.saved-panel,.modal{background:var(--surface);border-color:var(--line)}
.search-row input{background:var(--surface-2);border-color:var(--line)}
footer{background:var(--surface);border-top-color:var(--line)} body.light footer{background:#fff}
.gallery-track img,.club-gallery-track img{filter:saturate(1.02)}
@media(hover:hover) and (pointer:fine){.gallery-track img:hover,.club-gallery-track img:hover{filter:saturate(1.07) brightness(1.02)}}
@media(max-width:760px){.hero,body.light .hero{min-height:500px;background-position:56% 48%}}
@media(max-width:390px){.hero,body.light .hero{background-position:58% 48%}}



/* ======================================================================
   KAMPUS — CONTROLLED MULTI-COLOUR MAIN-WEBSITE PASS
   Neutral surfaces + colourful identity cues. Official logo is locked.
   ====================================================================== */
:root{
  --k-coral:#ff4f68;--k-blue:#58a6ff;--k-green:#4fd18b;--k-gold:#f3bd55;
  --k-violet:#9b86ff;--k-teal:#43d3c0;
}

/* Official KAMPUS mark — never theme-shift this. */
.brand-main{color:#172033!important}.brand-star{color:#ff4053!important}.brand small{color:#657188!important}
.nav,body.light .nav{background:rgba(255,255,255,.96)!important;border-bottom-color:#e3e7ed!important}
.nav-links a{color:#667085!important}.nav-links a:hover,.nav-links a.active{color:#172033!important}
.nav-links a:nth-child(1).active:after{background:var(--k-coral)!important}
.nav-links a:nth-child(2).active:after{background:var(--k-blue)!important}
.nav-links a:nth-child(3).active:after{background:var(--k-green)!important}
.nav-links a:nth-child(4).active:after{background:var(--k-violet)!important}
.nav-links a:nth-child(5).active:after{background:var(--k-gold)!important}
.icon-btn,.menu-btn,body.light .icon-btn,body.light .menu-btn{background:#f7f8fa!important;color:#263141!important;border-color:#dde2e8!important}
@media(hover:hover) and (pointer:fine){.icon-btn:hover,.menu-btn:hover,body.light .icon-btn:hover,body.light .menu-btn:hover{background:#fff!important;border-color:#cbd3dd!important}}

/* Base remains calm in both themes. */
body:not(.light){--bg:#0d1013;--surface:#13171b;--surface-2:#191e23;--card:#14191d;--text:#f5f7fa;--heading:#fff;--body-copy:#cbd1d8;--muted:#98a2ae;--line:#293039;--line-strong:#3a4551}
body.light{--bg:#f6f7f9;--surface:#ffffff;--surface-2:#f2f4f7;--card:#ffffff;--text:#18202b;--heading:#111820;--body-copy:#44505f;--muted:#667386;--line:#e0e5eb;--line-strong:#cbd3dd}
body{background:var(--bg)!important}

/* Compact live strip — only appears when there are events today. */
.today-strip-section{padding:16px 0 4px;background:var(--bg)}
.today-strip{display:flex;align-items:center;gap:14px;padding:12px 14px;border:1px solid var(--line);border-radius:16px;background:var(--surface);box-shadow:var(--shadow-soft);min-width:0;overflow:hidden;position:relative}
.today-strip:before{content:"";position:absolute;left:0;right:0;top:0;height:2px;background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal))}
.today-strip-intro{display:flex;align-items:center;gap:10px;flex:0 0 auto;padding-right:12px;border-right:1px solid var(--line)}
.today-live-dot{width:9px;height:9px;border-radius:50%;background:var(--k-coral);box-shadow:0 0 0 4px color-mix(in srgb,var(--k-coral) 18%,transparent)}
.today-strip-intro small{display:block;font-size:9px;font-weight:950;letter-spacing:.13em;color:var(--k-coral)}
.today-strip-intro strong{display:block;font-size:12px;margin-top:2px;white-space:nowrap}
.today-strip-events{display:flex;gap:8px;min-width:0;flex:1;overflow-x:auto;scrollbar-width:none}.today-strip-events::-webkit-scrollbar{display:none}
.today-mini{--tone:var(--k-blue);display:flex;align-items:center;gap:9px;flex:0 0 auto;max-width:250px;min-height:48px;padding:8px 11px;border-radius:12px;border:1px solid color-mix(in srgb,var(--tone) 30%,var(--line));background:color-mix(in srgb,var(--tone) 7%,var(--surface-2));color:var(--text);cursor:pointer;text-align:left;transition:transform .16s ease,border-color .16s ease,background .16s ease}
.today-tone-1{--tone:var(--k-coral)}.today-tone-2{--tone:var(--k-blue)}.today-tone-3{--tone:var(--k-green)}.today-tone-4{--tone:var(--k-gold)}.today-tone-5{--tone:var(--k-violet)}.today-tone-6{--tone:var(--k-teal)}
.today-mini-time{font-size:10px;font-weight:950;color:var(--tone);white-space:nowrap}.today-mini-copy{min-width:0}.today-mini strong{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.today-mini small{display:block;margin-top:2px;font-size:10px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.today-strip-all{flex:0 0 auto;font-size:11px;font-weight:900;color:var(--muted);white-space:nowrap}.today-strip-all:hover{color:var(--text)}
@media(hover:hover) and (pointer:fine){.today-mini:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--tone) 60%,var(--line));background:color-mix(in srgb,var(--tone) 11%,var(--surface-2))}}

/* Clear directory navigation for first-time users. */
.directory-back{display:inline-flex;align-items:center;gap:7px;margin:3px 0 12px;padding:8px 11px;border:1px solid var(--line);border-radius:999px;background:var(--surface);color:var(--muted);font-size:11px;font-weight:900;transition:transform .15s ease,color .15s ease,border-color .15s ease,background .15s ease}
.directory-back:hover{color:var(--text);border-color:color-mix(in srgb,var(--k-blue) 42%,var(--line));background:color-mix(in srgb,var(--k-blue) 6%,var(--surface));transform:translateX(-2px)}
.directory-back+.directory-hero{margin-top:0}

/* Every major homepage section gets its own identity colour. */
#homeClubsSection .eyebrow{color:var(--k-blue)!important}#homeEventsSection .eyebrow{color:var(--k-green)!important}#gallery .eyebrow{color:var(--k-violet)!important}#homeAboutSection .eyebrow{color:var(--k-gold)!important}
#homeClubsSection:before{background:linear-gradient(90deg,transparent,var(--k-blue),transparent)!important}
#homeEventsSection:before{background:linear-gradient(90deg,transparent,var(--k-green),transparent)!important}
#gallery:before{background:linear-gradient(90deg,transparent,var(--k-violet),transparent)!important}
#homeAboutSection:before{background:linear-gradient(90deg,transparent,var(--k-gold),transparent)!important}

/* Colour-coded cards: lively accents, quiet surfaces. */
.club-card,.event-card,.home-event-card{--tone:var(--k-coral);position:relative!important;isolation:isolate;background:linear-gradient(145deg,color-mix(in srgb,var(--tone) 5%,var(--card)),var(--card) 44%)!important;border-color:color-mix(in srgb,var(--tone) 20%,var(--line))!important}
.club-card:before,.event-card:before,.home-event-card:before{content:"";position:absolute;z-index:6;left:0;right:0;top:0;height:3px;background:var(--tone);pointer-events:none}
