.club-grid>.club-card:nth-child(6n+2),.event-grid>.event-card:nth-child(6n+2),.home-event-list>.home-event-card:nth-child(6n+2){--tone:var(--k-blue)}
.club-grid>.club-card:nth-child(6n+3),.event-grid>.event-card:nth-child(6n+3),.home-event-list>.home-event-card:nth-child(6n+3){--tone:var(--k-green)}
.club-grid>.club-card:nth-child(6n+4),.event-grid>.event-card:nth-child(6n+4),.home-event-list>.home-event-card:nth-child(6n+4){--tone:var(--k-gold)}
.club-grid>.club-card:nth-child(6n+5),.event-grid>.event-card:nth-child(6n+5),.home-event-list>.home-event-card:nth-child(6n+5){--tone:var(--k-violet)}
.club-grid>.club-card:nth-child(6n),.event-grid>.event-card:nth-child(6n),.home-event-list>.home-event-card:nth-child(6n){--tone:var(--k-teal)}
.club-card .btn.primary{background:color-mix(in srgb,var(--tone) 82%,#111)!important;border-color:transparent!important;color:#fff!important}
.club-card:nth-child(6n+4) .btn.primary{color:#151719!important;background:color-mix(in srgb,var(--k-gold) 88%,#fff)!important}
.event-club{color:var(--tone)!important}.date-badge{border-color:color-mix(in srgb,var(--tone) 40%,rgba(255,255,255,.12))!important}.date-badge span{color:var(--tone)!important}
.status.today{background:color-mix(in srgb,var(--k-coral) 14%,transparent)!important;color:#ff8292!important;border-color:color-mix(in srgb,var(--k-coral) 28%,transparent)!important}
.status:not(.today){background:color-mix(in srgb,var(--tone) 10%,var(--surface-2))!important;color:color-mix(in srgb,var(--tone) 72%,var(--text))!important;border-color:color-mix(in srgb,var(--tone) 22%,var(--line))!important}

/* Buttons each have a role colour — same meaning everywhere. */
.btn.view-club-btn,body.light .btn.view-club-btn{background:color-mix(in srgb,var(--k-blue) 8%,var(--surface))!important;border-color:color-mix(in srgb,var(--k-blue) 34%,var(--line))!important;color:color-mix(in srgb,var(--k-blue) 78%,var(--text))!important}
.btn.register-btn{background:linear-gradient(135deg,var(--k-coral),#ff7555)!important;border-color:transparent!important;color:#fff!important}
.share-btn,.club-share-btn{background:color-mix(in srgb,var(--k-teal) 8%,var(--surface-2))!important;border-color:color-mix(in srgb,var(--k-teal) 30%,var(--line))!important;color:color-mix(in srgb,var(--k-teal) 76%,var(--text))!important}
.save-btn.saved{background:color-mix(in srgb,var(--k-violet) 12%,var(--surface-2))!important;border-color:color-mix(in srgb,var(--k-violet) 38%,var(--line))!important;color:color-mix(in srgb,var(--k-violet) 78%,var(--text))!important}

/* Directory filter colours cycle without becoming loud. */
#clubFilters .pill,#eventFilters .pill{--pill-tone:var(--k-blue)}
#clubFilters .pill:nth-child(6n+1),#eventFilters .pill:nth-child(6n+1){--pill-tone:var(--k-coral)}
#clubFilters .pill:nth-child(6n+2),#eventFilters .pill:nth-child(6n+2){--pill-tone:var(--k-blue)}
#clubFilters .pill:nth-child(6n+3),#eventFilters .pill:nth-child(6n+3){--pill-tone:var(--k-green)}
#clubFilters .pill:nth-child(6n+4),#eventFilters .pill:nth-child(6n+4){--pill-tone:var(--k-gold)}
#clubFilters .pill:nth-child(6n+5),#eventFilters .pill:nth-child(6n+5){--pill-tone:var(--k-violet)}
