#clubFilters .pill,#eventFilters .pill{border-color:color-mix(in srgb,var(--pill-tone) 22%,var(--line));background:color-mix(in srgb,var(--pill-tone) 4%,var(--surface));transition:.15s ease}
#clubFilters .pill.active,#eventFilters .pill.active{background:color-mix(in srgb,var(--pill-tone) 78%,#15191e)!important;border-color:transparent!important;color:#fff!important;box-shadow:0 6px 16px color-mix(in srgb,var(--pill-tone) 15%,transparent)}
#clubFilters .pill:nth-child(6n+4).active,#eventFilters .pill:nth-child(6n+4).active{color:#16191d!important;background:var(--k-gold)!important}

/* View Club: each information/section block has its own colour identity. */
.club-hero-card{border-top:0!important}.club-hero-card:after{height:3px!important;background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal))!important}
.club-meta-card{--meta-tone:var(--k-coral);position:relative!important;border-top:1px solid color-mix(in srgb,var(--meta-tone) 30%,var(--line))!important;background:linear-gradient(145deg,color-mix(in srgb,var(--meta-tone) 7%,var(--surface-2)),var(--surface-2))!important}
.club-meta-card:nth-child(1){--meta-tone:var(--k-coral)}.club-meta-card:nth-child(2){--meta-tone:var(--k-gold)}.club-meta-card:nth-child(3){--meta-tone:var(--k-blue)}.club-meta-card:nth-child(4){--meta-tone:var(--k-green)}
.club-meta-card:before{content:"";position:absolute!important;left:0!important;top:10px!important;bottom:10px!important;width:3px!important;height:auto!important;border-radius:99px;background:var(--meta-tone)!important;opacity:1!important}
.club-meta-card strong{color:color-mix(in srgb,var(--meta-tone) 62%,var(--muted))!important}
.club-section{--section-tone:var(--k-coral);background:linear-gradient(135deg,color-mix(in srgb,var(--section-tone) 4%,var(--surface)),var(--surface) 46%)!important;border-color:color-mix(in srgb,var(--section-tone) 16%,var(--line))!important}
.club-section.tone-coral{--section-tone:var(--k-coral)}.club-section.tone-blue{--section-tone:var(--k-blue)}.club-section.tone-violet{--section-tone:var(--k-violet)}.club-section.tone-green{--section-tone:var(--k-green)}
.club-section-head{justify-content:flex-start!important}.club-section-head:before{background:var(--section-tone)!important;box-shadow:0 0 0 4px color-mix(in srgb,var(--section-tone) 8%,transparent)}
.club-section-head h2{color:var(--heading)!important}
.club-page-logo,.club-logo{background:#fff!important}
.club-cover-static,.club-card-cover-static{cursor:default!important}.club-cover-static *,.club-card-cover-static *{cursor:default!important}
.club-identity.no-logo{padding-top:24px}

/* About page/home: colour-coded concepts instead of one repeated accent. */
.about-home-panel,.about-story-main,.about-side-note,.about-value,.about-bottom-strip{background:var(--surface)!important}
.about-point,.about-value{--about-tone:var(--k-blue)}.about-point:nth-child(1),.about-value:nth-child(1){--about-tone:var(--k-blue)}.about-point:nth-child(2),.about-value:nth-child(2){--about-tone:var(--k-violet)}.about-point:nth-child(3),.about-value:nth-child(3){--about-tone:var(--k-green)}
.about-point{border-color:color-mix(in srgb,var(--about-tone) 18%,var(--line))!important;background:linear-gradient(135deg,color-mix(in srgb,var(--about-tone) 6%,var(--surface-2)),var(--surface-2))!important}
.about-point>span,.about-point:nth-child(2)>span,.about-point:nth-child(3)>span,body.light .about-point>span,body.light .about-point:nth-child(2)>span,body.light .about-point:nth-child(3)>span{background:color-mix(in srgb,var(--about-tone) 12%,var(--surface))!important;border-color:color-mix(in srgb,var(--about-tone) 30%,var(--line))!important;color:var(--about-tone)!important}
.about-value{border-top:3px solid var(--about-tone)!important}.about-value-icon,.about-value:nth-child(2) .about-value-icon,.about-value:nth-child(3) .about-value-icon{background:color-mix(in srgb,var(--about-tone) 10%,var(--surface-2))!important;border-color:color-mix(in srgb,var(--about-tone) 28%,var(--line))!important;color:var(--about-tone)!important}
.about-side-note{border-top:3px solid var(--k-violet)!important}.about-story-main{border-top:3px solid var(--k-blue)!important}.about-bottom-strip{border-top:3px solid var(--k-gold)!important}
.about-orbit span:nth-child(1){background:var(--k-teal)!important}.about-orbit span:nth-child(2){background:var(--k-violet)!important}.about-orbit span:nth-child(3){background:var(--k-coral)!important}

/* Search, Saved, modal and footer get small colour cues, not coloured walls. */
.search-panel{border-top:2px solid var(--k-blue)!important}.search-row input:focus{border-color:var(--k-blue)!important;box-shadow:0 0 0 3px color-mix(in srgb,var(--k-blue) 12%,transparent)!important}
.saved-panel{border-top:2px solid var(--k-violet)!important}.saved-item{--saved-tone:var(--k-violet);position:relative}.saved-item:nth-child(3n+2){--saved-tone:var(--k-blue)}.saved-item:nth-child(3n){--saved-tone:var(--k-green)}.saved-item:before{content:"";position:absolute;left:0;top:18px;bottom:18px;width:2px;background:var(--saved-tone);border-radius:99px}
.modal{border-top:3px solid var(--k-green)!important}.modal-meta span:nth-child(1){border-color:color-mix(in srgb,var(--k-coral) 35%,var(--line));color:color-mix(in srgb,var(--k-coral) 72%,var(--text))}.modal-meta span:nth-child(2){border-color:color-mix(in srgb,var(--k-blue) 35%,var(--line));color:color-mix(in srgb,var(--k-blue) 72%,var(--text))}.modal-meta span:nth-child(3){border-color:color-mix(in srgb,var(--k-gold) 35%,var(--line));color:color-mix(in srgb,var(--k-gold) 72%,var(--text))}.modal-meta span:nth-child(4){border-color:color-mix(in srgb,var(--k-green) 35%,var(--line));color:color-mix(in srgb,var(--k-green) 72%,var(--text))}
footer{position:relative!important}footer:before{content:"";position:absolute;top:-1px;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal))}

/* Better media consistency: stable ratios, clean crops, no banner lightbox. */
.club-banner,.home-event-media,.event-poster{overflow:hidden}.club-banner>img,.home-event-media>img{object-fit:cover!important;object-position:center!important}.event-poster>img{object-fit:contain!important;object-position:center!important}
.gallery-track img,.club-gallery-track img{border-radius:16px!important;object-fit:cover!important;object-position:center!important}
.club-logo,.club-page-logo{object-fit:contain!important;padding:6px!important}

/* Subtle motion only — no dramatic page effects. */
@media(prefers-reduced-motion:no-preference){
  .page-wrap.active .directory-back{animation:kampusSoftIn .28s ease both}
  .page-wrap.active .directory-hero{animation:kampusSoftIn .38s .03s ease both}
  .page-wrap.active .club-card,.page-wrap.active .event-card{animation:kampusSoftIn .34s ease both}
  .club-page.show .club-hero-card{animation:kampusSoftIn .34s ease both}
  .club-page.show .club-section{animation:kampusSoftIn .36s ease both}
  .today-strip-section:not(.hidden) .today-strip{animation:kampusSoftIn .32s ease both}
  @keyframes kampusSoftIn{from{opacity:.01;transform:translateY(7px)}to{opacity:1;transform:none}}
}
@media(hover:hover) and (pointer:fine){
  .club-card:hover,.event-card:hover,.home-event-card:hover{border-color:color-mix(in srgb,var(--tone) 42%,var(--line))!important;box-shadow:0 18px 42px color-mix(in srgb,var(--tone) 8%,rgba(0,0,0,.28))!important}
  .zoomable-logo:hover{transform:translateY(-3px) scale(1.065)!important;box-shadow:0 14px 30px rgba(0,0,0,.25)!important}
}

/* Small visual polish. */
::selection{background:color-mix(in srgb,var(--k-violet) 36%,transparent)}
:focus-visible{outline-color:color-mix(in srgb,var(--k-blue) 72%,#fff)!important}
.empty,.load-error{background:color-mix(in srgb,var(--k-blue) 3%,var(--surface))!important}

@media(max-width:760px){
  .today-strip-section{padding-top:10px}.today-strip{gap:10px;padding:11px 12px;overflow:visible;flex-wrap:wrap}.today-strip-intro{width:100%;border-right:0;border-bottom:1px solid var(--line);padding:0 0 9px}.today-strip-events{width:calc(100% - 58px)}.today-mini{max-width:220px}.today-strip-all{margin-left:auto}
  .directory-back{margin-top:0;margin-bottom:10px;min-height:40px}
  .nav,body.light .nav{background:rgba(255,255,255,.98)!important}
}


/* KAMPUS website-share action: same circular nav control, subtle confirmation only. */
#websiteShareBtn.share-success{border-color:rgba(79,209,139,.65);background:rgba(79,209,139,.12)}
body.light #websiteShareBtn.share-success{border-color:rgba(34,163,100,.45);background:rgba(79,209,139,.13)}
#websiteShareBtn.share-success svg{stroke:#4fd18b}

/* =====================================================================
   KAMPUS — CONSOLIDATED MAIN SYSTEM
   Older exploratory theme pass removed. The blocks below are the active
   visual/interaction source of truth for the public site.
   ===================================================================== */
:root{
  /* Compatibility aliases for older structural rules still in the base stylesheet. */
  --sky:var(--k-blue);--leaf:var(--k-green);--teal:var(--k-teal);--violet:var(--k-violet);
}
/* =====================================================================
   KAMPUS — FINAL MULTI-COLOUR SYSTEM V3
   Neutral foundations + meaningful colour in BOTH modes.
   Official KAMPUS wordmark/star stay locked and are not theme-shifted.
   ===================================================================== */

:root{
  --k-coral:#ff4f68;
  --k-blue:#58a6ff;
  --k-green:#4fd18b;
  --k-gold:#f3bd55;
  --k-violet:#9b86ff;
  --k-teal:#43d3c0;
  --k-orange:#ff8a55;
}

/* Dark palette: true charcoal, not blue-black. */
body:not(.light){
  --bg:#0c0e10;
  --surface:#121519;
  --surface-2:#181c21;
  --card:#14181d;
  --text:#f6f7f9;
  --heading:#ffffff;
  --body-copy:#d0d6dd;
  --muted:#9ba5b1;
  --line:#2a3038;
  --line-strong:#3b4551;
  --shadow:0 18px 48px rgba(0,0,0,.34);
  --shadow-soft:0 9px 26px rgba(0,0,0,.20);
}

/* Light palette: still calm, but colour is intentionally visible. */
body.light{
  --bg:#f7f7f4;
  --surface:#ffffff;
  --surface-2:#f4f5f6;
  --card:#ffffff;
  --text:#1c2430;
  --heading:#131b27;
  --body-copy:#455367;
  --muted:#68768a;
  --line:#dfe4ea;
  --line-strong:#c8d0da;
  --k-coral:#df4f63;
  --k-blue:#397bc4;
  --k-green:#36845a;
  --k-gold:#a97928;
  --k-violet:#6f5fbd;
  --k-teal:#2d827e;
  --k-orange:#d46f43;
  --shadow:0 16px 38px rgba(26,34,45,.10);
  --shadow-soft:0 8px 22px rgba(26,34,45,.07);
}

/* Official logo: absolutely independent of theme colours. */
.brand-main{color:#172033!important}
.brand-star{color:#ff4053!important}
.brand small{color:#657188!important}

/* White navbar is deliberate: it protects the official logo in both modes. */
.nav,body.light .nav{
  background:rgba(255,255,255,.97)!important;
  border-bottom-color:#e2e6ec!important;
}
.nav-links a{color:#687386!important}
.nav-links a:hover,.nav-links a.active{color:#172033!important}
.icon-btn,.menu-btn,body.light .icon-btn,body.light .menu-btn{
  background:#f8f9fb!important;color:#263141!important;border-color:#dce2e9!important
}

/* Active navigation colours. */
.nav-links a:nth-child(1).active:after{background:var(--k-coral)!important}
.nav-links a:nth-child(2).active:after{background:var(--k-blue)!important}
.nav-links a:nth-child(3).active:after{background:var(--k-green)!important}
.nav-links a:nth-child(4).active:after{background:var(--k-violet)!important}
.nav-links a:nth-child(5).active:after{background:var(--k-gold)!important}

/* Mode-independent page atmosphere. */
body{
  background:
    radial-gradient(circle at 8% 18%,color-mix(in srgb,var(--k-green) 5%,transparent),transparent 30rem),
    radial-gradient(circle at 92% 30%,color-mix(in srgb,var(--k-blue) 5%,transparent),transparent 32rem),
    radial-gradient(circle at 50% 88%,color-mix(in srgb,var(--k-violet) 4%,transparent),transparent 30rem),
    var(--bg)!important;
}
body.light{
  background:
    radial-gradient(circle at 7% 16%,color-mix(in srgb,var(--k-green) 8%,transparent),transparent 30rem),
    radial-gradient(circle at 94% 32%,color-mix(in srgb,var(--k-blue) 8%,transparent),transparent 34rem),
    radial-gradient(circle at 52% 88%,color-mix(in srgb,var(--k-violet) 6%,transparent),transparent 31rem),
    var(--bg)!important;
}

/* Homepage hero stays photographic in BOTH modes; light mode never washes it out. */
.hero{
  background-size:cover!important;
  background-position:center 52%!important;
  background-repeat:no-repeat!important;
}
body.light .hero{
  filter:none!important;
}
body.light .hero:after{
  background:linear-gradient(transparent,color-mix(in srgb,var(--bg) 92%,transparent))!important;
}

/* Homepage sections: each gets a quiet colour atmosphere. */
#homeClubsSection{--section-tone:var(--k-blue)}
#homeEventsSection{--section-tone:var(--k-green)}
#gallery{--section-tone:var(--k-violet)}
#homeAboutSection{--section-tone:var(--k-gold)}
#homeClubsSection,#homeEventsSection,#gallery,#homeAboutSection{
  background:
    linear-gradient(180deg,color-mix(in srgb,var(--section-tone) 4%,var(--bg)),var(--bg) 82%)!important;
}
body.light #homeClubsSection,
body.light #homeEventsSection,
body.light #gallery,
body.light #homeAboutSection{
  background:
    linear-gradient(180deg,color-mix(in srgb,var(--section-tone) 10%,#fff),var(--bg) 84%)!important;
}
#homeClubsSection .eyebrow{color:var(--k-blue)!important}
#homeEventsSection .eyebrow{color:var(--k-green)!important}
#gallery .eyebrow{color:var(--k-violet)!important}
#homeAboutSection .eyebrow{color:var(--k-gold)!important}

/* The page directories also carry their own colour atmosphere. */
#clubsPage{--page-tone:var(--k-blue)}
#eventsPage{--page-tone:var(--k-green)}
#aboutPage{--page-tone:var(--k-violet)}
#clubsPage .page-section,#eventsPage .page-section,#aboutPage .page-section{
  background:
    radial-gradient(circle at 4% 10%,color-mix(in srgb,var(--page-tone) 7%,transparent),transparent 26rem),
    radial-gradient(circle at 94% 70%,color-mix(in srgb,var(--k-gold) 3%,transparent),transparent 27rem);
}
body.light #clubsPage .page-section,
body.light #eventsPage .page-section,
body.light #aboutPage .page-section{
  background:
    radial-gradient(circle at 4% 10%,color-mix(in srgb,var(--page-tone) 11%,transparent),transparent 27rem),
    radial-gradient(circle at 95% 72%,color-mix(in srgb,var(--k-gold) 6%,transparent),transparent 28rem);
}

/* Directory heroes retain their existing design, with a clean multicolour top rule. */
.directory-hero{position:relative!important}
.directory-hero:before{
  content:""!important;position:absolute!important;left:0!important;right:0!important;top:0!important;
  height:3px!important;z-index:3!important;pointer-events:none!important;
  background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal))!important;
}

/* ABOUT HERO: real campus photography, not a blank black block. */
.about-hero{
  background-image:
    linear-gradient(90deg,rgba(8,12,18,.88) 0%,rgba(8,12,18,.68) 42%,rgba(8,12,18,.30) 72%,rgba(8,12,18,.16) 100%),
    linear-gradient(180deg,rgba(7,10,14,.04),rgba(7,10,14,.48)),
    url("data:image/webp;base64,")!important;
  background-size:cover!important;
  background-position:center 37%!important;
  border-color:color-mix(in srgb,var(--k-violet) 30%,var(--line))!important;
}
body.light .about-hero{
  background-image:
    linear-gradient(90deg,rgba(10,14,20,.82) 0%,rgba(10,14,20,.59) 42%,rgba(10,14,20,.24) 72%,rgba(10,14,20,.11) 100%),
    linear-gradient(180deg,rgba(8,12,17,.02),rgba(8,12,17,.34)),
    url("data:image/webp;base64,")!important;
}
.about-hero .eyebrow{color:#d9d1ff!important}
.about-hero h1,.about-hero p{color:#fff!important;text-shadow:0 4px 22px rgba(0,0,0,.32)}

/* ABOUT PAGE — every concept has a different colour; no repeated red labels. */
.about-story-main{
  --about-tone:var(--k-blue);
  border:1px solid color-mix(in srgb,var(--about-tone) 34%,var(--line))!important;
  border-top:3px solid var(--about-tone)!important;
  background:linear-gradient(145deg,color-mix(in srgb,var(--about-tone) 8%,var(--surface)),var(--surface) 58%)!important;
}
.about-story-main>.eyebrow{color:var(--k-blue)!important}
.about-side-note{
  --about-tone:var(--k-violet);
  border:1px solid color-mix(in srgb,var(--about-tone) 34%,var(--line))!important;
  border-top:3px solid var(--about-tone)!important;
  background:
    radial-gradient(circle at 78% 16%,color-mix(in srgb,var(--k-teal) 10%,transparent),transparent 12rem),
    linear-gradient(145deg,color-mix(in srgb,var(--about-tone) 10%,var(--surface)),var(--surface) 60%)!important;
}
.about-side-note .eyebrow{color:var(--k-violet)!important}
body.light .about-story-main{
  background:linear-gradient(145deg,color-mix(in srgb,var(--k-blue) 11%,#fff),#fff 62%)!important;
}
body.light .about-side-note{
  background:
    radial-gradient(circle at 78% 16%,color-mix(in srgb,var(--k-teal) 12%,transparent),transparent 12rem),
    linear-gradient(145deg,color-mix(in srgb,var(--k-violet) 12%,#fff),#fff 62%)!important;
}

/* Value cards are explicitly BLUE / VIOLET / GREEN in both themes. */
.about-value:nth-child(1){--about-tone:var(--k-blue)}
.about-value:nth-child(2){--about-tone:var(--k-violet)}
.about-value:nth-child(3){--about-tone:var(--k-green)}
.about-value{
  border:1px solid color-mix(in srgb,var(--about-tone) 30%,var(--line))!important;
  border-top:3px solid var(--about-tone)!important;
  background:linear-gradient(155deg,color-mix(in srgb,var(--about-tone) 8%,var(--surface)),var(--surface) 62%)!important;
}
body.light .about-value{
  background:linear-gradient(155deg,color-mix(in srgb,var(--about-tone) 13%,#fff),#fff 64%)!important;
}
.about-value-icon{
  background:color-mix(in srgb,var(--about-tone) 14%,var(--surface-2))!important;
  color:var(--about-tone)!important;
  border-color:color-mix(in srgb,var(--about-tone) 38%,var(--line))!important;
}
body.light .about-value-icon{
  background:color-mix(in srgb,var(--about-tone) 13%,#fff)!important;
}
.about-bottom-strip{
  border:1px solid color-mix(in srgb,var(--k-gold) 34%,var(--line))!important;
  border-top:3px solid var(--k-gold)!important;
  background:linear-gradient(100deg,
    color-mix(in srgb,var(--k-gold) 8%,var(--surface)),
    color-mix(in srgb,var(--k-teal) 4%,var(--surface)) 52%,
    var(--surface))!important;
}
body.light .about-bottom-strip{
  background:linear-gradient(100deg,
    color-mix(in srgb,var(--k-gold) 14%,#fff),
    color-mix(in srgb,var(--k-teal) 8%,#fff) 55%,
    #fff)!important;
}
.about-bottom-strip .eyebrow{color:var(--k-gold)!important}

/* Homepage About panel gets colour too, but stays simple. */
.about-home-panel{
  border-color:color-mix(in srgb,var(--k-gold) 24%,var(--line))!important;
  background:linear-gradient(135deg,
    color-mix(in srgb,var(--k-blue) 6%,var(--surface)),
    color-mix(in srgb,var(--k-violet) 5%,var(--surface)) 48%,
    color-mix(in srgb,var(--k-gold) 7%,var(--surface)))!important;
}
body.light .about-home-panel{
  background:linear-gradient(135deg,
    color-mix(in srgb,var(--k-blue) 10%,#fff),
    color-mix(in srgb,var(--k-violet) 9%,#fff) 48%,
    color-mix(in srgb,var(--k-gold) 11%,#fff))!important;
}
.about-point:nth-child(1){--about-tone:var(--k-blue)}
.about-point:nth-child(2){--about-tone:var(--k-violet)}
.about-point:nth-child(3){--about-tone:var(--k-green)}
.about-point{
  background:color-mix(in srgb,var(--about-tone) 7%,var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--about-tone) 28%,var(--line))!important;
}
body.light .about-point{
  background:color-mix(in srgb,var(--about-tone) 10%,#fff)!important;
}

/* Cards across Home / Clubs / Events: colour should be visible, not merely a tiny line. */
.club-card,.event-card,.home-event-card{
  background:linear-gradient(145deg,
    color-mix(in srgb,var(--tone) 7%,var(--card)),
    var(--card) 58%)!important;
  border-color:color-mix(in srgb,var(--tone) 30%,var(--line))!important;
}
body.light .club-card,
body.light .event-card,
body.light .home-event-card{
  background:linear-gradient(145deg,
    color-mix(in srgb,var(--tone) 12%,#fff),
    #fff 62%)!important;
  border-color:color-mix(in srgb,var(--tone) 36%,var(--line))!important;
}
.club-card:before,.event-card:before,.home-event-card:before{height:3px!important}

/* Chips now use their category hue in both modes. */
.club-chip{
  background:color-mix(in srgb,var(--chip,#8fa2bb) 11%,var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--chip,#8fa2bb) 38%,var(--line))!important;
  color:var(--text)!important;
}
body.light .club-chip{
  background:color-mix(in srgb,var(--chip,#8fa2bb) 13%,#fff)!important;
  border-color:color-mix(in srgb,var(--chip,#8fa2bb) 42%,var(--line))!important;
}

/* Filters are visibly multicoloured in light mode as well. */
#clubFilters .pill,#eventFilters .pill{
  background:color-mix(in srgb,var(--pill-tone) 7%,var(--surface))!important;
  border-color:color-mix(in srgb,var(--pill-tone) 30%,var(--line))!important;
}
body.light #clubFilters .pill,
body.light #eventFilters .pill{
  background:color-mix(in srgb,var(--pill-tone) 11%,#fff)!important;
  border-color:color-mix(in srgb,var(--pill-tone) 38%,var(--line))!important;
}
#clubFilters .pill.active,#eventFilters .pill.active{
  background:var(--pill-tone)!important;color:#fff!important;border-color:transparent!important;
}
#clubFilters .pill:nth-child(6n+4).active,#eventFilters .pill:nth-child(6n+4).active{
  color:#1b1e20!important;
}

/* VIEW CLUB — four separate section colours, independent of generated classes. */
.club-page{
  background:
    radial-gradient(circle at 8% 8%,color-mix(in srgb,var(--k-blue) 7%,transparent),transparent 27rem),
    radial-gradient(circle at 92% 28%,color-mix(in srgb,var(--k-violet) 6%,transparent),transparent 30rem),
    radial-gradient(circle at 48% 92%,color-mix(in srgb,var(--k-green) 4%,transparent),transparent 28rem),
    var(--bg)!important;
}
body.light .club-page{
  background:
    radial-gradient(circle at 8% 8%,color-mix(in srgb,var(--k-blue) 10%,transparent),transparent 27rem),
    radial-gradient(circle at 92% 28%,color-mix(in srgb,var(--k-violet) 9%,transparent),transparent 30rem),
    radial-gradient(circle at 48% 92%,color-mix(in srgb,var(--k-green) 7%,transparent),transparent 28rem),
    var(--bg)!important;
}
.club-hero-card{
  background:linear-gradient(145deg,
    color-mix(in srgb,var(--k-blue) 4%,var(--surface)),
    color-mix(in srgb,var(--k-violet) 3%,var(--surface)) 55%,
    var(--surface))!important;
  border-color:color-mix(in srgb,var(--k-blue) 18%,var(--line))!important;
}
body.light .club-hero-card{
  background:linear-gradient(145deg,
    color-mix(in srgb,var(--k-blue) 8%,#fff),
    color-mix(in srgb,var(--k-violet) 6%,#fff) 55%,
    #fff)!important;
}
.club-hero-card:after{
  background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal))!important;
}

/* Metadata cards: coral / gold / blue / green. */
.club-meta-card:nth-child(1){--meta-tone:var(--k-coral)!important}
.club-meta-card:nth-child(2){--meta-tone:var(--k-gold)!important}
.club-meta-card:nth-child(3){--meta-tone:var(--k-blue)!important}
.club-meta-card:nth-child(4){--meta-tone:var(--k-green)!important}
.club-meta-card{
  background:linear-gradient(145deg,
    color-mix(in srgb,var(--meta-tone) 9%,var(--surface-2)),
    var(--surface-2) 68%)!important;
  border-color:color-mix(in srgb,var(--meta-tone) 28%,var(--line))!important;
}
body.light .club-meta-card{
  background:linear-gradient(145deg,
    color-mix(in srgb,var(--meta-tone) 13%,#fff),
    #fff 68%)!important;
  border-color:color-mix(in srgb,var(--meta-tone) 36%,var(--line))!important;
}

/* About club = BLUE, Gallery = VIOLET, Videos = TEAL, Upcoming = GREEN. */
#clubContent>.club-section:nth-of-type(1){--section-tone:var(--k-blue)!important}
#clubContent>.club-section:nth-of-type(2){--section-tone:var(--k-violet)!important}
#clubContent>.club-section:nth-of-type(3){--section-tone:var(--k-teal)!important}
#clubContent>.club-section:nth-of-type(4){--section-tone:var(--k-green)!important}
#clubContent>.club-section{
  background:linear-gradient(140deg,
    color-mix(in srgb,var(--section-tone) 7%,var(--surface)),
    var(--surface) 64%)!important;
  border-color:color-mix(in srgb,var(--section-tone) 29%,var(--line))!important;
}
body.light #clubContent>.club-section{
  background:linear-gradient(140deg,
    color-mix(in srgb,var(--section-tone) 12%,#fff),
    #fff 66%)!important;
  border-color:color-mix(in srgb,var(--section-tone) 36%,var(--line))!important;
}
.club-section-head:before{background:var(--section-tone)!important}
#clubContent>.club-section:nth-of-type(1) .club-section-head h2{color:color-mix(in srgb,var(--k-blue) 72%,var(--heading))!important}
#clubContent>.club-section:nth-of-type(2) .club-section-head h2{color:color-mix(in srgb,var(--k-violet) 72%,var(--heading))!important}
#clubContent>.club-section:nth-of-type(3) .club-section-head h2{color:color-mix(in srgb,var(--k-teal) 72%,var(--heading))!important}
#clubContent>.club-section:nth-of-type(4) .club-section-head h2{color:color-mix(in srgb,var(--k-green) 72%,var(--heading))!important}

/* Happening Today gets the same six-colour language in both modes. */
.today-strip{
  background:linear-gradient(120deg,
    color-mix(in srgb,var(--k-coral) 4%,var(--surface)),
    color-mix(in srgb,var(--k-blue) 3%,var(--surface)) 36%,
    color-mix(in srgb,var(--k-green) 3%,var(--surface)) 70%,
    var(--surface))!important;
}
body.light .today-strip{
  background:linear-gradient(120deg,
    color-mix(in srgb,var(--k-coral) 8%,#fff),
    color-mix(in srgb,var(--k-blue) 7%,#fff) 36%,
    color-mix(in srgb,var(--k-green) 7%,#fff) 70%,
    #fff)!important;
}
body.light .today-mini{
  background:color-mix(in srgb,var(--tone) 12%,#fff)!important;
  border-color:color-mix(in srgb,var(--tone) 38%,var(--line))!important;
}

/* Saved, Search, Event modal and Footer: colour cues stay visible in both modes. */
.search-panel{border-top:3px solid var(--k-blue)!important}
.saved-panel{border-top:3px solid var(--k-violet)!important}
.modal{border-top:3px solid var(--k-green)!important}
body.light .search-panel{
  background:linear-gradient(145deg,color-mix(in srgb,var(--k-blue) 7%,#fff),#fff 55%)!important;
}
body.light .saved-panel{
  background:linear-gradient(145deg,color-mix(in srgb,var(--k-violet) 8%,#fff),#fff 55%)!important;
}
body.light .modal{
  background:linear-gradient(145deg,color-mix(in srgb,var(--k-green) 6%,#fff),#fff 58%)!important;
}
footer{
  background:linear-gradient(115deg,
    color-mix(in srgb,var(--k-coral) 3%,var(--surface)),
    color-mix(in srgb,var(--k-blue) 3%,var(--surface)) 42%,
    color-mix(in srgb,var(--k-violet) 3%,var(--surface)) 72%,
    var(--surface))!important;
}
body.light footer{
  background:linear-gradient(115deg,
    color-mix(in srgb,var(--k-coral) 8%,#fff),
    color-mix(in srgb,var(--k-blue) 7%,#fff) 42%,
    color-mix(in srgb,var(--k-violet) 7%,#fff) 72%,
    #fff)!important;
}

/* Buttons retain consistent semantic colours. */
.btn.view-club-btn,body.light .btn.view-club-btn{
  background:color-mix(in srgb,var(--k-blue) 11%,var(--surface))!important;
  border-color:color-mix(in srgb,var(--k-blue) 40%,var(--line))!important;
  color:color-mix(in srgb,var(--k-blue) 82%,var(--text))!important;
}
.btn.register-btn{
  background:linear-gradient(135deg,var(--k-coral),var(--k-orange))!important;
  color:#fff!important;border-color:transparent!important;
}
.share-btn,.club-share-btn{
  background:color-mix(in srgb,var(--k-teal) 11%,var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--k-teal) 38%,var(--line))!important;
  color:color-mix(in srgb,var(--k-teal) 78%,var(--text))!important;
}
.save-btn.saved{
  background:color-mix(in srgb,var(--k-violet) 13%,var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--k-violet) 40%,var(--line))!important;
  color:color-mix(in srgb,var(--k-violet) 78%,var(--text))!important;
}

/* Multicolour footer rule, selection and focus feedback. */
footer:before{
  background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal))!important;
}
::selection{background:color-mix(in srgb,var(--k-violet) 35%,transparent)}
:focus-visible{outline-color:color-mix(in srgb,var(--k-blue) 76%,#fff)!important}

/* Mobile keeps the same colour language without extra clutter. */
@media(max-width:760px){
  .nav,body.light .nav{background:rgba(255,255,255,.985)!important}
  .about-hero{background-position:58% center!important}
  .about-story-main,.about-side-note,.about-value,.about-bottom-strip{box-shadow:none!important}
}

/* =====================================================================
   KAMPUS — VIDEO REVIEW COHERENCE PASS
   Core rule: one clear colour identity per section/component group.
   Colour changes by section, not randomly inside the same component.
   Official KAMPUS wordmark + star are intentionally untouched.
   ===================================================================== */

:root{
  --k-coral:#ff5268;
  --k-blue:#4f9fff;
  --k-green:#43c986;
  --k-gold:#f0b94f;
  --k-violet:#9178f6;
  --k-teal:#39bdb0;
  --k-orange:#ff825c;
}

/* True neutral foundations — colour comes from sections, not the canvas. */
body:not(.light){
  --bg:#0b0d0f;
  --surface:#121519;
  --surface-2:#181c20;
  --card:#14181c;
  --text:#f6f7f8;
  --heading:#ffffff;
  --body-copy:#d1d6dc;
  --muted:#9da6b0;
  --line:#2a3036;
  --line-strong:#3a424b;
}
body.light{
  --bg:#fbfaf7;
  --surface:#ffffff;
  --surface-2:#f4f3ef;
  --card:#ffffff;
  --text:#172033;
  --heading:#101827;
  --body-copy:#415069;
  --muted:#69758a;
  --line:#dcdedc;
  --line-strong:#c8ccc9;
  background:
    radial-gradient(circle at 4% 8%,rgba(79,159,255,.075),transparent 27rem),
    radial-gradient(circle at 96% 28%,rgba(145,120,246,.060),transparent 30rem),
    radial-gradient(circle at 52% 88%,rgba(67,201,134,.055),transparent 29rem),
    var(--bg)!important;
}

/* Route colour = simple orientation cue. */
.nav-links [data-route="home"].active:after{background:var(--k-coral)!important}
.nav-links [data-route="clubs"].active:after{background:var(--k-blue)!important}
.nav-links [data-route="events"].active:after{background:var(--k-coral)!important}
.nav-links [data-route="gallery"].active:after{background:var(--k-violet)!important}
.nav-links [data-route="about"].active:after{background:var(--k-green)!important}

/* ---------------------------------------------------------------------
   HOME: each major section has ONE colour family.
   This removes the "same dull grey everywhere" problem without chaos.
   --------------------------------------------------------------------- */
#homeClubsSection{--section-tone:var(--k-blue)!important}
#homeEventsSection{--section-tone:var(--k-coral)!important}
#gallery{--section-tone:var(--k-violet)!important}
#homeAboutSection{--section-tone:var(--k-green)!important}

#homeClubsSection,#homeEventsSection,#gallery,#homeAboutSection{
  background:
    radial-gradient(circle at 93% 12%,color-mix(in srgb,var(--section-tone) 8%,transparent),transparent 23rem),
    linear-gradient(180deg,color-mix(in srgb,var(--section-tone) 6%,var(--bg)),var(--bg) 78%)!important;
}
body.light #homeClubsSection{
  background:linear-gradient(180deg,#edf6ff 0%,#f8fbff 62%,var(--bg) 100%)!important;
}
body.light #homeEventsSection{
  background:linear-gradient(180deg,#fff0f3 0%,#fff8f8 62%,var(--bg) 100%)!important;
}
body.light #gallery{
  background:linear-gradient(180deg,#f3efff 0%,#faf8ff 62%,var(--bg) 100%)!important;
}
body.light #homeAboutSection{
  background:linear-gradient(180deg,#eefaf4 0%,#f8fcfa 62%,var(--bg) 100%)!important;
}
#homeClubsSection:before{background:linear-gradient(90deg,transparent,var(--k-blue),transparent)!important}
#homeEventsSection:before{background:linear-gradient(90deg,transparent,var(--k-coral),transparent)!important}
#gallery:before{background:linear-gradient(90deg,transparent,var(--k-violet),transparent)!important}
#homeAboutSection:before{background:linear-gradient(90deg,transparent,var(--k-green),transparent)!important}
#homeClubsSection .eyebrow{color:var(--k-blue)!important}
#homeEventsSection .eyebrow{color:var(--k-coral)!important}
#gallery .eyebrow{color:var(--k-violet)!important}
#homeAboutSection .eyebrow{color:var(--k-green)!important}

/* Club cards stay BLUE as a family; individual cards don't randomly change hue. */
#homeClubsSection .club-card,#clubsPage .club-card{
  --tone:var(--k-blue)!important;
