#clubUpcomingEvents .home-event-card[data-tone]:before{background:var(--tone)!important}

/* Keep one event = one colour family. */
.home-event-card[data-tone] .event-club,.event-card[data-tone] .event-club{color:var(--tone)!important}
.home-event-card[data-tone] .status,.event-card[data-tone] .status,
.home-event-card[data-tone] .urgency-badge,.event-card[data-tone] .urgency-badge{
