.home-event-card[data-tone] .view-club-btn,.event-card[data-tone] .view-club-btn,
.home-event-card[data-tone] .share-btn,.event-card[data-tone] .share-btn,
.home-event-card[data-tone] .save-btn,.event-card[data-tone] .save-btn{
  background:color-mix(in srgb,var(--tone) 10%,var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--tone) 40%,var(--line))!important;
