body.light #clubsPage .page-section{background:radial-gradient(circle at 8% 4%,rgba(79,159,255,.12),transparent 28rem),var(--bg)!important}
body.light #eventsPage .page-section{background:radial-gradient(circle at 92% 5%,rgba(255,82,104,.11),transparent 28rem),var(--bg)!important}
body.light #aboutPage .page-section{background:radial-gradient(circle at 8% 6%,rgba(145,120,246,.10),transparent 27rem),radial-gradient(circle at 92% 72%,rgba(67,201,134,.08),transparent 26rem),var(--bg)!important}

/* HAPPENING TODAY: pulse, next-time context, and category-aware mini cards. */
.today-live-dot{animation:kampusLivePulse 1.9s ease-out infinite!important;box-shadow:0 0 0 0 color-mix(in srgb,var(--k-coral) 48%,transparent)}
@keyframes kampusLivePulse{0%{box-shadow:0 0 0 0 color-mix(in srgb,var(--k-coral) 45%,transparent)}70%{box-shadow:0 0 0 8px transparent}100%{box-shadow:0 0 0 0 transparent}}
.today-strip-intro strong{display:block;line-height:1.3}
.today-strip-next{display:block;margin-top:2px;font-size:10px;font-weight:760;color:var(--muted)}
.today-mini[data-tone]{
  --tone:var(--k-blue);
  background:linear-gradient(145deg,color-mix(in srgb,var(--tone) 12%,var(--surface-2)),var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--tone) 42%,var(--line))!important;
  position:relative;overflow:hidden;
}
.today-mini[data-tone]:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--tone)}
.today-mini[data-tone] .today-mini-time{color:var(--tone)!important}
body.light .today-mini[data-tone]{background:linear-gradient(145deg,color-mix(in srgb,var(--tone) 20%,#fff),#fff)!important;border-color:color-mix(in srgb,var(--tone) 50%,#d7dce2)!important}

/* Urgency badges. */
.event-badges{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:9px}
.urgency-badge,.registration-urgency{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:999px;padding:5px 8px;font-size:9px;font-weight:950;letter-spacing:.08em;text-transform:uppercase;line-height:1.05}
.registration-urgency{background:color-mix(in srgb,var(--k-gold) 13%,var(--surface-2));border-color:color-mix(in srgb,var(--k-gold) 42%,var(--line));color:#f0c66d}
body.light .registration-urgency{background:#fff3cf;border-color:#e5c468;color:#70510b}
.modal-urgency{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 11px}

/* Image consistency + category-coloured missing artwork. */
.event-poster-wrap{aspect-ratio:4/3!important;min-height:0!important}
.event-poster,.home-event-media{background:color-mix(in srgb,var(--tone,var(--k-coral)) 6%,var(--surface-2))!important}
.event-card .media-shell>img,.home-event-card .media-shell>img{object-fit:contain!important;object-position:center!important}
.event-card .media-shell.media-error,.home-event-card .media-shell.media-error{
  background:radial-gradient(circle at 72% 26%,color-mix(in srgb,var(--tone,var(--k-coral)) 28%,transparent),transparent 45%),linear-gradient(145deg,color-mix(in srgb,var(--tone,var(--k-coral)) 15%,var(--surface-2)),var(--surface-2))!important;
}
.event-card .media-fallback,.home-event-card .media-fallback{color:color-mix(in srgb,var(--tone,var(--k-coral)) 72%,var(--text))!important}
.club-banner>img{object-fit:cover!important;object-position:center!important}
.club-page .club-cover>img{object-fit:cover!important;object-position:center!important}
.gallery-track img,.club-gallery-track img{aspect-ratio:3/2!important;width:240px!important;height:auto!important;object-fit:cover!important;object-position:center!important}

/* Save / share / filter micro-interactions. */
.save-btn{position:relative;overflow:visible}
.save-btn.just-saved{animation:kampusBookmarkBounce .38s cubic-bezier(.2,.9,.25,1.25)}
.save-btn.just-unsaved{animation:kampusBookmarkOut .24s ease}
@keyframes kampusBookmarkBounce{0%{transform:scale(1)}45%{transform:scale(.82) rotate(-6deg)}78%{transform:scale(1.16) rotate(3deg)}100%{transform:scale(1) rotate(0)}}
@keyframes kampusBookmarkOut{0%{transform:scale(1)}50%{transform:scale(.88)}100%{transform:scale(1)}}
.share-btn.copied{animation:kampusSharePop .32s cubic-bezier(.2,.9,.25,1.2)!important}
@keyframes kampusSharePop{0%{transform:scale(.88)}65%{transform:scale(1.12)}100%{transform:scale(1)}}
.pill{position:relative;overflow:hidden;transition:transform .18s ease,border-color .18s ease,background .18s ease,color .18s ease!important}
.pill:after{content:"";position:absolute;left:50%;bottom:3px;width:16px;height:2px;border-radius:99px;background:currentColor;opacity:0;transform:translateX(-50%) scaleX(.25);transition:opacity .18s ease,transform .22s ease}
.pill.active:after{opacity:.68;transform:translateX(-50%) scaleX(1)}
@media(hover:hover) and (pointer:fine){.pill:hover{transform:translateY(-1px)}.today-mini:hover{transform:translateY(-2px)}}

/* Designed empty and error states. */
.empty,.saved-empty,.load-error{position:relative;overflow:hidden;border-style:dashed!important;text-align:left!important;padding:24px!important;background:linear-gradient(145deg,color-mix(in srgb,var(--k-blue) 6%,var(--surface)),color-mix(in srgb,var(--k-violet) 4%,var(--surface)))!important}
body.light .empty,body.light .saved-empty,body.light .load-error{background:linear-gradient(145deg,#edf7ff,#f7f2ff 65%,#fff)!important;border-color:#cad9e8!important}
.empty:before,.saved-empty:before,.load-error:before{content:"";position:absolute;inset:0 auto 0 0;width:3px;background:linear-gradient(var(--k-blue),var(--k-violet))}
.empty-state-icon{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;margin-bottom:11px;background:color-mix(in srgb,var(--k-blue) 12%,var(--surface-2));border:1px solid color-mix(in srgb,var(--k-blue) 30%,var(--line));color:var(--k-blue);font-weight:950;font-size:15px}
.empty strong,.load-error strong{display:block;color:var(--heading);font-size:15px;margin-bottom:5px}
.empty span{display:block;color:var(--muted);font-size:12px;line-height:1.5}

/* Saved events keep the event's category colour without becoming noisy. */
.saved-item[data-tone]{
  border-left:3px solid var(--tone)!important;
  background:linear-gradient(90deg,color-mix(in srgb,var(--tone) 8%,var(--surface-2)),transparent 72%)!important;
  border-radius:10px;padding-left:10px!important;margin:3px 0;
}
body.light .saved-item[data-tone]{background:linear-gradient(90deg,color-mix(in srgb,var(--tone) 13%,#fff),transparent 72%)!important}
.modal[data-tone] .empty{background:linear-gradient(145deg,color-mix(in srgb,var(--tone) 10%,var(--surface)),var(--surface))!important;border-color:color-mix(in srgb,var(--tone) 36%,var(--line))!important}
body.light .modal[data-tone] .empty{background:linear-gradient(145deg,color-mix(in srgb,var(--tone) 16%,#fff),#fff)!important;border-color:color-mix(in srgb,var(--tone) 42%,#d8dde3)!important}

/* Lightbox: counter + tappable progress dots. */
.lightbox{touch-action:pan-y;overscroll-behavior:contain}
.lightbox img{transition:transform .18s ease,opacity .16s ease!important;user-select:none;-webkit-user-drag:none}
.lightbox-dots{position:absolute;bottom:58px;left:50%;transform:translateX(-50%);display:flex;align-items:center;justify-content:center;gap:7px;max-width:min(78vw,480px);padding:7px 10px;border-radius:999px;background:rgba(12,15,19,.72);border:1px solid rgba(255,255,255,.13);backdrop-filter:blur(10px)}
.lightbox-dot{width:7px;height:7px;padding:0;border:0;border-radius:50%;background:#ffffff54;cursor:pointer;transition:transform .18s ease,background .18s ease;width:7px!important;min-height:7px!important}
.lightbox-dot.active{background:#fff;transform:scale(1.45)}
.lightbox-count{font-variant-numeric:tabular-nums;letter-spacing:.04em}

/* Purposeful reveal animation. Elements are invisible only after JS opts them in. */
.reveal-ready{opacity:0;transform:translateY(10px)}
.reveal-ready.reveal-in{opacity:1;transform:none;transition:opacity .34s ease,transform .34s ease}
.reveal-ready:nth-child(2){transition-delay:.035s}.reveal-ready:nth-child(3){transition-delay:.07s}.reveal-ready:nth-child(4){transition-delay:.105s}

/* Small details that make the UI feel responsive without becoming noisy. */
.btn,.icon-btn,.save-btn,.share-btn,.today-mini,.directory-back{will-change:auto}
.btn:active,.icon-btn:active,.today-mini:active,.directory-back:active{transform:scale(.97)!important}
.date-badge{box-shadow:0 8px 18px rgba(0,0,0,.22)}
.directory-back{transition:transform .18s ease,border-color .18s ease,background .18s ease}
@media(hover:hover) and (pointer:fine){.directory-back:hover{transform:translateX(-2px)}}

/* Performance: defer expensive below-fold rendering without changing layout. */
@supports(content-visibility:auto){
  #homeClubsSection,#homeEventsSection,#gallery,#homeAboutSection{content-visibility:auto;contain-intrinsic-size:700px}
}

/* Mobile interaction pass: manual gallery swiping, larger tap targets, safer modals. */
@media(max-width:760px){
  .btn,.save-btn,.share-btn,.icon-btn,.menu-btn,.pill,.directory-back{min-height:44px}
  .save-btn,.share-btn{width:44px;height:44px;flex-basis:44px}
  .home-event-actions,.event-body .card-actions{gap:8px}
  .home-event-actions .view-club-btn,.home-event-actions .register-btn{flex:1 1 120px}
  .event-body .card-actions .view-club-btn,.event-body .card-actions .register-btn{flex:1 1 120px}
  .gallery-viewport,.club-gallery-window{overflow-x:auto!important;overscroll-behavior-x:contain;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch;mask-image:none!important}
  .gallery-viewport::-webkit-scrollbar,.club-gallery-window::-webkit-scrollbar{display:none}
  .gallery-track,.club-gallery-track{animation:none!important;width:max-content!important;padding:8px 14px 12px!important}
  .gallery-track img,.club-gallery-track img{width:min(72vw,260px)!important;scroll-snap-align:center;scroll-snap-stop:always}
  .lightbox{padding:54px 8px 92px!important}
  .lightbox img{max-height:74dvh!important;max-width:calc(100vw - 20px)!important}
  .lightbox-dots{bottom:56px;max-width:82vw;gap:6px}
  .lightbox-count{bottom:16px!important}
  .modal{max-height:calc(100dvh - 18px)!important}
  .modal-copy{padding-bottom:calc(22px + env(safe-area-inset-bottom))!important}
  .nav-links.open{max-height:calc(100dvh - 78px);overflow-y:auto;overscroll-behavior:contain}
  .club-page .club-cover>img{object-fit:contain!important}
}

@media(prefers-reduced-motion:reduce){
  .today-live-dot,.save-btn.just-saved,.save-btn.just-unsaved,.share-btn.copied{animation:none!important}
  .reveal-ready{opacity:1!important;transform:none!important}.reveal-ready.reveal-in{transition:none!important}
}
.save-data .gallery-track,.save-data .club-gallery-track{animation:none!important}

/* Saved Events refinement: one clear tone per event, calmer container, true circles. */
.saved-panel{
  border:1px solid var(--line)!important;
  border-top:1px solid var(--line)!important;
  border-radius:22px!important;
  overflow:hidden!important;
  box-shadow:0 24px 70px rgba(0,0,0,.36)!important;
  position:absolute;
}
.saved-panel:before{
  content:"";
  position:absolute;
  top:0;left:0;right:0;
  height:3px;
  background:linear-gradient(90deg,var(--k-coral),var(--k-gold),var(--k-green),var(--k-blue),var(--k-violet),var(--k-teal));
  z-index:2;
  pointer-events:none;
}
.saved-head{padding:22px 24px 18px!important;align-items:flex-start!important}
.saved-list{padding:12px 16px 18px!important}
.saved-group{padding:2px 0 8px!important}
.saved-group-title{padding:12px 2px 7px!important;font-size:9.5px!important;letter-spacing:.13em!important}

.saved-close{
  width:42px!important;
  height:42px!important;
  min-width:42px!important;
  min-height:42px!important;
  max-width:42px!important;
  max-height:42px!important;
  flex:0 0 42px!important;
  aspect-ratio:1/1!important;
  padding:0!important;
  margin:0!important;
  border-radius:50%!important;
  display:grid!important;
  place-items:center!important;
  line-height:1!important;
  font-size:22px!important;
  font-weight:500!important;
  background:var(--surface-2)!important;
  border:1px solid var(--line)!important;
  color:var(--text)!important;
}
.saved-close:hover{background:color-mix(in srgb,var(--k-coral) 9%,var(--surface-2))!important;border-color:color-mix(in srgb,var(--k-coral) 32%,var(--line))!important}

.saved-item[data-tone]{
  position:relative!important;
  grid-template-columns:56px minmax(0,1fr) auto!important;
  gap:12px!important;
  align-items:center!important;
  margin:7px 0!important;
  padding:12px 12px 12px 14px!important;
  border:1px solid color-mix(in srgb,var(--tone) 24%,var(--line))!important;
  border-left:3px solid var(--tone)!important;
  border-radius:14px!important;
  background:linear-gradient(90deg,color-mix(in srgb,var(--tone) 7%,var(--surface-2)),var(--surface-2) 68%)!important;
  overflow:hidden!important;
}
.saved-item[data-tone]:before{display:none!important;content:none!important}
body.light .saved-item[data-tone]{
  background:linear-gradient(90deg,color-mix(in srgb,var(--tone) 10%,#fff),#fff 70%)!important;
  border-color:color-mix(in srgb,var(--tone) 30%,#d9dee6)!important;
  border-left-color:var(--tone)!important;
}
.saved-item[data-tone] .saved-date{
  width:50px!important;height:50px!important;min-width:50px!important;min-height:50px!important;
  border-radius:50%!important;
  background:var(--surface)!important;
  border:1px solid color-mix(in srgb,var(--tone) 24%,var(--line))!important;
  box-shadow:none!important;
}
body.light .saved-item[data-tone] .saved-date{background:#fff!important}
.saved-item[data-tone] .saved-date span{color:var(--tone)!important}
.saved-copy h4{margin-bottom:5px!important;font-size:15px!important}
.saved-copy p{font-size:12px!important;color:var(--muted)!important}
.saved-actions{gap:8px!important}
.saved-item[data-tone] .saved-open{
  color:var(--tone)!important;
  background:color-mix(in srgb,var(--tone) 8%,transparent)!important;
  border:1px solid color-mix(in srgb,var(--tone) 24%,transparent)!important;
  border-radius:9px!important;
  padding:8px 10px!important;
  min-height:36px!important;
  font-weight:900!important;
}
.saved-item[data-tone] .saved-open:hover{background:color-mix(in srgb,var(--tone) 14%,var(--surface-2))!important}
.saved-item[data-tone] .save-btn.saved{
  width:38px!important;height:38px!important;min-width:38px!important;min-height:38px!important;flex:0 0 38px!important;
  border-radius:10px!important;
  background:color-mix(in srgb,var(--tone) 13%,var(--surface-2))!important;
  border-color:color-mix(in srgb,var(--tone) 42%,var(--line))!important;
  color:var(--tone)!important;
}
body.light .saved-item[data-tone] .save-btn.saved{
  background:color-mix(in srgb,var(--tone) 11%,#fff)!important;
  border-color:color-mix(in srgb,var(--tone) 38%,#d9dee6)!important;
  color:color-mix(in srgb,var(--tone) 82%,#18202a)!important;
}
.saved-item[data-tone="gold"] .saved-open,
.saved-item[data-tone="gold"] .save-btn.saved{color:color-mix(in srgb,var(--k-gold) 72%,#fff)!important}
body.light .saved-item[data-tone="gold"] .saved-open,
body.light .saved-item[data-tone="gold"] .save-btn.saved{color:#8a6410!important}

@media(max-width:760px){
  .saved-panel{position:fixed!important;left:10px!important;right:10px!important;width:auto!important}
  .saved-head{padding:20px 18px 16px!important}
  .saved-list{padding:9px 10px 14px!important}
  .saved-close{width:40px!important;height:40px!important;min-width:40px!important;min-height:40px!important;max-width:40px!important;max-height:40px!important;flex-basis:40px!important}
  .saved-item[data-tone]{grid-template-columns:50px minmax(0,1fr)!important;padding:11px 10px 11px 12px!important}
  .saved-item[data-tone] .saved-date{width:46px!important;height:46px!important;min-width:46px!important;min-height:46px!important}
  .saved-actions{grid-column:2!important;justify-content:flex-start!important;margin-top:2px!important}
}
/* Homepage hero is one locked asset in both themes; only overlay strength changes. */
.hero{
  background-image:linear-gradient(90deg,rgba(7,12,9,.76) 0%,rgba(7,12,9,.56) 34%,rgba(7,12,9,.24) 65%,rgba(7,12,9,.05) 100%),linear-gradient(180deg,rgba(6,10,8,.02),rgba(6,10,8,.04) 68%,rgba(6,10,8,.34)),url("data:image/webp;base64,")!important;
  background-size:cover!important;background-position:center 57%!important;background-repeat:no-repeat!important;
}
body.light .hero{
  background-image:linear-gradient(90deg,rgba(18,27,20,.60) 0%,rgba(18,27,20,.40) 34%,rgba(18,27,20,.12) 66%,rgba(18,27,20,.015) 100%),linear-gradient(180deg,rgba(20,28,21,.01),rgba(20,28,21,.02) 70%,rgba(20,28,21,.18)),url("data:image/webp;base64,")!important;
  background-size:cover!important;background-position:center 57%!important;background-repeat:no-repeat!important;
}
@media(max-width:760px){.hero,body.light .hero{background-position:center 60%!important}}
@media(max-width:390px){.hero,body.light .hero{background-position:center 62%!important}}



/* Mobile galleries: one reliable motion model. CSS marquee is desktop-only;
   JavaScript handles continuous mobile movement so touch/swipe remains native. */
@media(max-width:760px){
  .gallery-viewport,.club-gallery-window{overflow-x:auto!important;overflow-y:hidden!important;scroll-snap-type:none!important;-webkit-overflow-scrolling:touch;scrollbar-width:none;touch-action:pan-x pan-y}
  .gallery-viewport::-webkit-scrollbar,.club-gallery-window::-webkit-scrollbar{display:none}
  .gallery-track,.club-gallery-track{animation:none!important;transform:none!important;will-change:auto!important;scroll-snap-type:none!important}
  .gallery-track img,.club-gallery-track img{scroll-snap-align:none!important;flex:none!important}
}

/* Focus rings use the active multicolour identity, but remain calm and readable. */
:focus-visible{outline:3px solid color-mix(in srgb,var(--k-blue) 58%,transparent)!important;outline-offset:3px!important}
.saved-close,.close-btn,.lightbox-nav,.icon-btn,.menu-btn{flex-shrink:0}

/* Prevent tap-highlight flashes that looked like accidental blue overlays. */
button,a,.zoomable-logo,.gallery-track img,.club-gallery-track img{-webkit-tap-highlight-color:transparent}

@media(prefers-reduced-motion:reduce){
  .gallery-track,.club-gallery-track{transition:none!important;animation:none!important}
}
